window.CODE_SAMPLES = {"signal": [{"title": "Pipeline orchestration", "path": "Suhani_PBEL_3.0-main 2/Suhani_PBEL_3.0-main/source code/src/pipeline.py", "code": "\"\"\"\nOrchestrates the full PART 1 + PART 2 pipeline end-to-end and writes\nresults to data/processed/ so the API can serve them without recomputing\non every request. Run this after dropping a new dataset into data/raw/,\nor on a schedule in production.\n\n    python -m src.pipeline\n\"\"\"\nimport logging\nimport pandas as pd\n\nfrom src.utils import allow_unverified_ssl_for_nltk_downloads\nallow_unverified_ssl_for_nltk_downloads()\n\nfrom src.config import DATA_PROCESSED\nfrom src.data.ingest import load_email_data, load_insider_labels\nfrom src.data.store import write_df\nfrom src.data.anonymize import anonymize_dataframe, pseudonymize_user\nfrom src.data.validate import validate_email_df\nfrom src.features.linguistic_features import extract_features_df\nfrom src.features.stylometry import extract_stylometry_df\nfrom src.features.network_features import extract_network_features_df\nfrom src.features.baseline_engine import BaselineEngine\nfrom src.features.drift_scoring import score_drift_df, aggregate_user_risk\nfrom src.features.trajectory import compute_trajectory_df\nfrom src.models.unsupervised.anomaly_detection import fit_isolation_forest, fit_dbscan_clusters\nfrom src.governance.audit_log import log_event\nfrom src.governance.bias_audit import audit_drift_by_style_proxy\nfrom src.governance.openscale_monitor import build_monitor_snapshot, compare_to_previous_snapshot\nfrom src.governance.alert_suppression import apply_context_aware_suppression\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n\ndef run_pipeline() -> dict:\n    logger.info(\"=== Starting pipeline run ===\")\n\n    raw = load_email_data()\n    validate_email_df(raw)\n\n    # Network-drift features (contact_degree, interaction_concentration) are\n    # computed from raw to/cc/bcc *before* anonymization, keyed to raw's own\n    # row index: anonymize_dataframe()'s single-string HMAC over the whole\n    # semicolon-joined `to` field is meant for the single-address `user`/\n    # `from` columns, not a multi-recipient list, so computing network\n    # features first and re-aligning by index afterward avoids depending on\n    # that column post-anonymization. Only the two resulting numeric columns\n    # are carried forward — no raw address ever leaves this block.\n    net_feats = extract_network_features_df(raw, user_col=\"user\", date_col=\"date\")\n    net_cols = net_feats[[\"contact_degree\", \"interaction_concentration\"]]\n\n    anon = anonymize_dataframe(raw)\n    anon = anon.join(net_cols)  # index-aligned; consent-filtered rows keep only their own values\n    feats = extract_features_df(anon)\n    feats = extract_stylometry_df(feats)\n\n    engine = BaselineEngine()\n    z_df = engine.replay(feats)\n    scored = score_drift_df(z_df)\n\n    user_risk = aggregate_user_risk(scored)\n\n    # Trajectory: fits each user's own chronological drift-score sequence\n    # (numpy.polyfit) to get trend_slope + acceleration, merged onto the\n    # existing level-based risk table rather than replacing it — see\n    # src/features/trajectory.py.\n    trajectory = compute_trajectory_df(scored, user_col=\"user\", date_col=\"date\")\n    user_risk = user_risk.merge(trajectory, on=\"user\", how=\"left\")\n\n    _, _, msg_with_anomaly = fit_isolation_forest(scored)\n    _, _, user_with_clusters = fit_dbscan_clusters(user_risk)\n\n    # Org-wide monitoring snapshot is computed here (rather than only in the\n    # governance-addenda block below) because context-aware alert\n    # suppression needs to know *before* persisting user_risk whether this\n    # run shows a correlated, organization-wide shift — see\n    # governance/alert_suppression.py. Kept in its own try/except, same\n    # graceful-degradation pattern as the rest of this function: a snapshot\n    # failure should never block the core scoring pipeline from persisting.\n    org_wide_shift_detected = False\n    snapshot = None\n    try:\n        snapshot = build_monitor_snapshot(scored, user_with_clusters)\n        snapshot_comparison = compare_to_previous_snapshot(snapshot)\n        org_wide_shift_detected = bool(snapshot_comparison[\"alerts\"])\n        if org_wide_shift_detected:\n            logger.warning(f\"Monitoring snapshot flagged org-wide feature drift: {snapshot_comparison['alerts']}\")\n    except Exception as e:\n        logger.warning(f\"Monitoring snapshot step failed, continuing without it: {e}\")\n\n    # Context-aware alert suppression: gates individual escalation on\n    # relative standing among this run's own (possibly also-elevated)\n    # population, raising the bar further when the whole org shifted\n    # together — see governance/alert_suppression.py.\n    user_with_clusters = apply_context_aware_suppression(\n        user_with_clusters, org_wide_shift_detected=org_wide_shift_detected\n    )\n\n    # persist for the API layer to read without recomputation\n    # NOTE: must write msg_with_anomaly (not the original `scored`) — it's the\n    # frame with IsolationForest's anomaly_score/is_anomaly columns attached.\n    # Writing `scored` here silently dropped those columns before they ever\n    # reached the API, even though the model ran and logged its results above.\n    #\n    # write_df (src/data/store.py) writes to the live Neon `scored_messages`/\n    # `user_risk` tables when DATABASE_URL is set — not just a local CSV —\n    # since a deployed API (e.g. on Vercel) has no persistent local disk to\n    # read data/processed/*.csv back from between requests or deploys.\n    write_df(msg_with_anomaly, \"scored_messages\")\n    write_df(user_with_clusters, \"user_risk\")\n\n    labels = load_insider_labels()\n    if labels is not None:\n        labels = labels.copy()\n        labels[\"user\"] = labels[\"user\"].map(pseudonymize_user)\n        labels.to_csv(DATA_PROCESSED / \"user_labels_pseudonymized.csv\", index=False)\n\n    top_flagged = user_with_clusters.sort_values(\"avg_drift_score\", ascending=False).head(10)\n    for _, row in top_flagged.iterrows():\n        log_event(\n            \"drift_flagged\",\n            row[\"user\"],\n            {\"avg_drift_score\": row[\"avg_drift_score\"], \"flagged_message_rate\": row[\"flagged_message_rate\"]},\n        )\n\n    # Governance addendum: a per-run fairness check on writing-style proxies\n    # — see governance/bias_audit.py. (The org-wide monitoring snapshot is\n    # computed earlier now, since alert suppression depends on it — see\n    # above.)\n    try:\n        bias_report = audit_drift_by_style_proxy(scored)\n        if bias_report[\"proxies_with_disparity_over_1_5x\"]:\n            logger.warning(\n                f\"Bias audit flagged possible disparity in: \"\n                f\"{bias_report['proxies_with_disparity_over_1_5x']} — see data/processed/reports/bias_audit.md\"\n            )\n    except Exception as e:\n        logger.warning(f\"Bias audit step failed, continuing without it: {e}\")\n\n    logger.info(f\"=== Pipeline run complete: {len(scored)} messages, {len(user_risk)} users ===\")\n    return {\n        \"n_messages\": len(scored),\n        \"n_users\": len(user_risk),\n        \"processed_dir\": str(DATA_PROCESSED),\n        \"org_wide_shift_detected\": org_wide_shift_detected,\n    }\n\n\nif __name__ == \"__main__\":\n    result = run_pipeline()\n    print(result)\n"}, {"title": "Drift scoring", "path": "Suhani_PBEL_3.0-main 2/Suhani_PBEL_3.0-main/source code/src/features/drift_scoring.py", "code": "\"\"\"\nPART 2 — Drift scoring.\n\nTurns the per-feature z-scores from baseline_engine.py into a single\ninterpretable drift score per message/user, using the config threshold\n(DRIFT_Z_THRESHOLD) to flag which features actually crossed into\n\"significant drift\" territory.\n\nThis is intentionally simple and auditable (a weighted absolute z-score\naverage + a flagged-feature count) rather than a black box, because the\ngovernance/ethics angle of this project depends on analysts being able to\nsee *why* a user was flagged, not just a bare score\n\"\"\"\nimport logging\nfrom typing import Dict, List\n\nimport pandas as pd\n\nfrom src.config import DRIFT_Z_THRESHOLD\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n# Guard rail: when a feature has near-zero variance in a user's baseline\n# window, a single differing value can produce an enormous raw z-score\n# (mathematically correct, but it would silently dominate the weighted\n# average and drown out every other signal). We clip |z| before weighting\n# so one near-constant feature can't blow up the overall drift score —\n# it still crosses DRIFT_Z_THRESHOLD and gets flagged, it just can't\n# multiply out to an uninterpretable magnitude.\nMAX_ABS_Z = 10.0\n\n# Not all features are equally diagnostic of insider-risk-relevant drift;\n# urgency and sentiment shifts matter more than e.g. readability alone.\n#\n# social_engineering_score weighted at 1.8, just under urgency_score (2.0):\n# it's a targeted-manipulation signal (authority spoofing, isolation framing,\n# etc.) rather than a general tone shift, so it's treated as similarly\n# diagnostic to urgency rather than left at the 1.0 default a brand-new,\n# uncalibrated feature would otherwise silently get.\nFEATURE_WEIGHTS = {\n    \"z_urgency_score\": 2.0,\n    \"z_social_engineering_score\": 1.8,\n    \"z_sentiment_polarity\": 1.5,\n    \"z_sentiment_subjectivity\": 1.0,\n    \"z_function_word_ratio\": 1.2,\n    \"z_lexical_diversity\": 1.0,\n    \"z_readability_flesch\": 0.8,\n    \"z_noun_ratio\": 0.7,\n    \"z_verb_ratio\": 0.7,\n    # Communication-network drift (src/dsa/communication_graph.py). Weighted\n    # close to sentiment/urgency rather than at the 1.0 default: a shrinking,\n    # concentrated circle is one of the best-documented pre-incident\n    # behaviors in real counterintelligence casework, not a minor stylistic\n    # wobble, so it's treated as similarly diagnostic to tone/urgency drift.\n    \"z_contact_degree\": 1.4,\n    \"z_interaction_concentration\": 1.6,\n}\n\n\ndef score_drift(z_row: Dict[str, float]) -> dict:\n    \"\"\"\n    Given a dict of z_<feature> -> z-score values (as produced by\n    BaselineEngine.replay), returns:\n      - drift_score: weighted mean absolute z-score (0 = no drift; grows unbounded)\n      - flagged_features: list of features whose |z| exceeded DRIFT_Z_THRESHOLD\n      - n_flagged: convenience count\n    \"\"\"\n    if not z_row:\n        return {\"drift_score\": 0.0, \"flagged_features\": [], \"n_flagged\": 0}\n\n    weighted_sum = 0.0\n    weight_total = 0.0\n    flagged: List[str] = []\n\n    for feat, z in z_row.items():\n        if pd.isna(z):\n            continue\n        w = FEATURE_WEIGHTS.get(feat, 1.0)\n        clipped_z = min(abs(z), MAX_ABS_Z)\n        weighted_sum += w * clipped_z\n        weight_total += w\n        if abs(z) >= DRIFT_Z_THRESHOLD:\n            flagged.append(feat.replace(\"z_\", \"\"))\n\n    drift_score = round(weighted_sum / weight_total, 4) if weight_total else 0.0\n    return {\"drift_score\": drift_score, \"flagged_features\": flagged, \"n_flagged\": len(flagged)}\n\n\ndef score_drift_df(z_df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"Apply score_drift row-wise across a DataFrame that already has z_* columns.\"\"\"\n    z_cols = [c for c in z_df.columns if c.startswith(\"z_\")]\n    logger.info(f\"Scoring drift across {len(z_df)} rows using {len(z_cols)} z-score features...\")\n\n    if not z_cols:\n        # No user in this batch has enough prior history yet to fill even one\n        # feature's baseline window (see BaselineEngine.is_ready) — e.g. a\n        # short/sparse real-data sample where nobody reaches\n        # BASELINE_WINDOW_SIZE messages. pandas' .apply(axis=1) over a\n        # zero-column DataFrame doesn't reliably reproduce a per-row Series of\n        # dicts, so handle this case explicitly instead of relying on it.\n        logger.warning(\n            \"No z-score columns present — no user in this batch has enough \"\n            \"message history yet to fill a baseline window. Every message is \"\n            \"being scored as drift_score=0.0 (not yet measurable), not as \"\n            \"'no drift detected'.\"\n        )\n        result_df = pd.DataFrame(\n            {\n                \"drift_score\": 0.0,\n                \"flagged_features\": [[] for _ in range(len(z_df))],\n                \"n_flagged\": 0,\n            },\n            index=z_df.index,\n        )\n        return pd.concat([z_df, result_df], axis=1)\n\n    results = z_df[z_cols].apply(lambda row: score_drift(row.dropna().to_dict()), axis=1)\n    result_df = pd.DataFrame(list(results), index=z_df.index)\n    return pd.concat([z_df, result_df], axis=1)\n\n\ndef aggregate_user_risk(scored_df: pd.DataFrame, user_col: str = \"user\") -> pd.DataFrame:\n    \"\"\"\n    Rolls per-message drift scores up to a per-user risk summary — this is\n    what feeds the Top-K heap (src/dsa/top_k_heap.py) for the analyst\n    dashboard's \"riskiest users this week\" view.\n    \"\"\"\n    agg = scored_df.groupby(user_col).agg(\n        avg_drift_score=(\"drift_score\", \"mean\"),\n        max_drift_score=(\"drift_score\", \"max\"),\n        n_messages=(\"drift_score\", \"count\"),\n        n_flagged_messages=(\"n_flagged\", lambda s: (s > 0).sum()),\n    ).reset_index()\n    agg[\"flagged_message_rate\"] = (agg[\"n_flagged_messages\"] / agg[\"n_messages\"]).round(4)\n    return agg.sort_values(\"avg_drift_score\", ascending=False)\n\n\nif __name__ == \"__main__\":\n    sample = {\"z_urgency_score\": 3.1, \"z_social_engineering_score\": 2.6, \"z_sentiment_polarity\": -2.8, \"z_readability_flesch\": 0.4}\n    print(score_drift(sample))\n"}, {"title": "Sliding-window statistics", "path": "Suhani_PBEL_3.0-main 2/Suhani_PBEL_3.0-main/source code/src/dsa/sliding_window.py", "code": "\"\"\"\nDSA: fixed-size sliding window with O(1) amortized rolling mean/variance.\n\nWhy not just call np.mean()/np.std() on a slice every time?\nRecomputing mean/variance from scratch on every new message is O(w) per\nupdate where w = window size. Across thousands of users each producing\nhundreds of messages, that's O(n * w) total. This structure updates\nincrementally in O(1) per insertion (amortized), giving O(n) total —\nthe difference matters once this runs per-user, per-day, at CERT-dataset\nscale (tens of thousands of employees).\n\nApproach: a deque holds the last `w` values. On insert we update a running\nsum and running sum-of-squares in O(1); when the window overflows we evict\nthe oldest value and adjust the same running totals in O(1). Mean and\n(population) variance are then simple arithmetic, no rescans.\n\nThis is a simplified two-pass-free variant of Welford's algorithm adapted\nfor a *bounded* window (Welford's classic form is for an unbounded stream).\n\"\"\"\nfrom collections import deque\n\n\nclass SlidingWindowStats:\n    def __init__(self, window_size: int):\n        if window_size <= 0:\n            raise ValueError(\"window_size must be positive\")\n        self.window_size = window_size\n        self._values = deque(maxlen=window_size)\n        self._sum = 0.0\n        self._sum_sq = 0.0\n\n    def push(self, value: float) -> None:\n        \"\"\"Add a new value, evicting the oldest if the window is full. O(1) amortized.\"\"\"\n        if len(self._values) == self.window_size:\n            oldest = self._values[0]  # will be auto-evicted by deque's maxlen\n            self._sum -= oldest\n            self._sum_sq -= oldest * oldest\n        self._values.append(value)\n        self._sum += value\n        self._sum_sq += value * value\n\n    @property\n    def count(self) -> int:\n        return len(self._values)\n\n    @property\n    def mean(self) -> float:\n        if not self._values:\n            return 0.0\n        return self._sum / len(self._values)\n\n    @property\n    def variance(self) -> float:\n        \"\"\"Population variance, clamped to >= 0 to guard against fp drift.\"\"\"\n        n = len(self._values)\n        if n == 0:\n            return 0.0\n        mean = self.mean\n        var = (self._sum_sq / n) - (mean * mean)\n        return max(var, 0.0)\n\n    @property\n    def std(self) -> float:\n        return self.variance ** 0.5\n\n    def z_score(self, value: float) -> float:\n        \"\"\"How many std-devs `value` is from this window's mean. 0.0 std -> 0.0 (no drift signal yet).\"\"\"\n        std = self.std\n        if std == 0.0:\n            return 0.0\n        return (value - self.mean) / std\n\n    def is_full(self) -> bool:\n        return len(self._values) == self.window_size\n\n    def snapshot(self) -> dict:\n        return {\n            \"count\": self.count,\n            \"mean\": round(self.mean, 4),\n            \"std\": round(self.std, 4),\n            \"window_size\": self.window_size,\n        }\n\n\nif __name__ == \"__main__\":\n    # quick self-test\n    w = SlidingWindowStats(window_size=5)\n    for v in [1, 2, 3, 4, 5, 100]:  # 100 should push out the \"1\" and spike the mean\n        w.push(v)\n    print(w.snapshot())\n    print(\"z-score of 100 given current window:\", w.z_score(100))\n"}, {"title": "Aho–Corasick matcher", "path": "Suhani_PBEL_3.0-main 2/Suhani_PBEL_3.0-main/source code/src/dsa/trie_phrase_matcher.py", "code": "\"\"\"\nDSA: Aho-Corasick automaton for multi-pattern phrase matching.\n\nWhy: we scan every message against ~20-100+ urgency / social-engineering\nphrases (config.URGENCY_PHRASES). Naively that's O(n_phrases * len(text))\nper message via repeated substring search. Aho-Corasick builds a trie of\nall patterns plus failure links, so a message of length m is scanned in\nO(m + matches) *regardless of how many phrases we're looking for* — this\nis what lets the phrase list grow to hundreds of entries without slowing\ndown per-message scanning.\n\nImplementation: classic Aho-Corasick (trie + BFS-built failure links +\noutput links), built once at startup from config.URGENCY_PHRASES and\nreused across all messages.\n\"\"\"\nfrom collections import deque\nfrom typing import List, Dict, Tuple\n\n\nclass _Node:\n    __slots__ = (\"children\", \"fail\", \"output\")\n\n    def __init__(self):\n        self.children: Dict[str, \"_Node\"] = {}\n        self.fail: \"_Node\" = None\n        self.output: List[str] = []  # phrases that end at this node\n\n\nclass AhoCorasick:\n    def __init__(self, phrases: List[str]):\n        self.root = _Node()\n        self.root.fail = self.root\n        self._phrases = [p.lower() for p in phrases]\n        self._build_trie()\n        self._build_failure_links()\n\n    def _build_trie(self):\n        for phrase in self._phrases:\n            node = self.root\n            for ch in phrase:\n                node = node.children.setdefault(ch, _Node())\n            node.output.append(phrase)\n\n    def _build_failure_links(self):\n        queue = deque()\n        for child in self.root.children.values():\n            child.fail = self.root\n            queue.append(child)\n\n        while queue:\n            current = queue.popleft()\n            for ch, child in current.children.items():\n                queue.append(child)\n                fail_node = current.fail\n                while fail_node is not self.root and ch not in fail_node.children:\n                    fail_node = fail_node.fail\n                child.fail = fail_node.children.get(ch, self.root) if fail_node is not child else self.root\n                if child.fail is child:\n                    child.fail = self.root\n                # merge output (a shorter phrase can be a suffix of a longer one)\n                child.output += child.fail.output\n\n    def scan(self, text: str) -> List[Tuple[str, int]]:\n        \"\"\"Return list of (phrase, end_index) matches in text. O(len(text) + matches).\"\"\"\n        text = text.lower()\n        node = self.root\n        matches: List[Tuple[str, int]] = []\n\n        for i, ch in enumerate(text):\n            while node is not self.root and ch not in node.children:\n                node = node.fail\n            node = node.children.get(ch, self.root)\n            for phrase in node.output:\n                matches.append((phrase, i))\n        return matches\n\n    def urgency_score(self, text: str) -> float:\n        \"\"\"\n        Simple normalized score: number of distinct matched phrases / total\n        phrases in the lexicon, capped at 1.0. Used as one input feature to\n        the risk model, not a verdict on its own.\n        \"\"\"\n        matches = self.scan(text)\n        if not matches or not self._phrases:\n            return 0.0\n        distinct = len({m[0] for m in matches})\n        return min(distinct / max(len(self._phrases), 1) * 5, 1.0)  # scaled so 1-2 hits already register\n\n\nif __name__ == \"__main__\":\n    from src.config import URGENCY_PHRASES\n    ac = AhoCorasick(URGENCY_PHRASES)\n    sample = \"Hey, this is urgent — please wire transfer the funds ASAP and don't tell anyone.\"\n    print(ac.scan(sample))\n    print(\"urgency_score:\", ac.urgency_score(sample))\n"}, {"title": "Investigation agent", "path": "Suhani_PBEL_3.0-main 2/Suhani_PBEL_3.0-main/source code/src/agents/investigation_agent.py", "code": "\"\"\"\nPART 3 — Agentic AI: autonomous multi-step investigation agent.\n\nEverything upstream of this module (features/, models/) produces a single\nnumber or a single sentence per user — a drift score, an anomaly flag, a\none-shot watsonx.ai explanation. This module adds an *agent*: given a\nflagged pseudonym, it plans and executes a short sequence of read-only\n\"tool calls\" against the project's own modules, accumulates the evidence\nit gathers, and — when watsonx.ai is configured — asks the model to reason\nover that accumulated evidence (not just a single row of stats) before\nproposing a next step. That plan-act-observe loop, with a visible,\nauditable trace of what it looked at and why, is what makes this \"agentic\"\nrather than just another single-shot model call like explain_drift().\n\nGuardrails (non-negotiable, matches README's \"it never acts autonomously\non a flag\"):\n  1. Every tool available to this agent is read-only. It has no access to\n     consent revocation, the QRadar export, or any other write/enforcement\n     path — those live in separate modules the agent never imports.\n  2. The agent's output is always a *recommendation* for a human analyst,\n     never an action. `requires_human_review` is hard-coded True and is\n     not something a prompt (or a compromised/hallucinating model) can\n     turn off.\n  3. Every investigation — including each intermediate tool call — is\n     written to the same tamper-evident audit log as every other scoring\n     decision in this system, so an agent run is reviewable after the\n     fact exactly like a model prediction is.\n  4. If watsonx.ai isn't configured, the agent still runs: it falls back\n     to a transparent, rule-based recommendation over the same evidence\n     it gathered, so the pipeline never silently loses this capability in\n     the free-tier/offline deployment.\n\"\"\"\nimport logging\nfrom typing import Optional\n\n\nfrom src.config import DRIFT_Z_THRESHOLD, WATSONX_ENABLED\nfrom src.data.store import read_df\nfrom src.governance.audit_log import log_event, get_recent_entries\nfrom src.governance.rag import retrieve\nfrom src.models.watsonx.client import explain_drift, _get_model\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\nAGENT_VERSION = \"agentic_investigation_v1\"\nRECENT_MESSAGES_LIMIT = 15\nPRIOR_EVENTS_SCANNED = 100\n\nACTIONS = (\"escalate_for_manual_review\", \"continue_monitoring\", \"no_action_needed\")\n\n\n# ---------------------------------------------------------------------------\n# Tools — each one is a thin, read-only wrapper around an existing module.\n# The agent's \"plan\" is the fixed order these run in below; keeping the\n# order deterministic (rather than letting an LLM freely choose which tool\n# to call, ReAct-style) means a run is reproducible and cheap to audit,\n# while the *reasoning over the results* is still delegated to watsonx.ai\n# when available. This is a deliberate, documented trade-off — same spirit\n# as rag.py choosing TF-IDF over an embedding model: inspectable over\n# maximally flexible.\n# ---------------------------------------------------------------------------\n\ndef _tool_get_risk_summary(pseudonym: str) -> Optional[dict]:\n    \"\"\"Read user risk through the project's storage abstraction.\n\n    On Vercel this resolves to Neon when DATABASE_URL is configured; during\n    local development it falls back to data/processed/user_risk.csv. Keeping\n    the agent on the same storage path as /api/users and /api/drift prevents\n    serverless requests from looking for a CSV that only exists on a laptop.\n    \"\"\"\n    df = read_df(\"user_risk\")\n    if df is None or df.empty or \"user\" not in df.columns:\n        return None\n    row = df[df[\"user\"] == pseudonym]\n    return row.iloc[0].to_dict() if not row.empty else None\n\n\ndef _tool_get_recent_messages(pseudonym: str) -> list:\n    \"\"\"Read recent scored messages through the same storage abstraction.\"\"\"\n    df = read_df(\"scored_messages\")\n    if df is None or df.empty or \"user\" not in df.columns:\n        return []\n\n    user_df = df[df[\"user\"] == pseudonym]\n    if user_df.empty:\n        return []\n\n    cols = [c for c in (\n        \"date\", \"drift_score\", \"n_flagged\", \"flagged_features\",\n        \"sentiment_polarity\", \"urgency_score\"\n    ) if c in user_df.columns]\n    return user_df[cols].tail(RECENT_MESSAGES_LIMIT).to_dict(orient=\"records\")\n\n\ndef _tool_get_prior_audit_events(pseudonym: str) -> list:\n    recent = get_recent_entries(n=PRIOR_EVENTS_SCANNED)\n    return [e for e in recent if e.get(\"user_pseudonym\") == pseudonym]\n\n\ndef _tool_search_governance_docs(query: str) -> list:\n    hits = retrieve(query, k=2)\n    return [{\"source\": h[\"source\"], \"score\": round(h[\"score\"], 3)} for h in hits]\n\n\n# ---------------------------------------------------------------------------\n# Reasoning step\n# ---------------------------------------------------------------------------\n\ndef _rule_based_recommendation(risk_summary: dict, prior_events: list) -> dict:\n    \"\"\"Transparent fallback used whenever watsonx.ai isn't configured, and\n    as the deterministic backstop if a live model call fails or returns an\n    unparseable response. Every branch is auditable from this source alone.\"\"\"\n    avg_drift = float(risk_summary.get(\"avg_drift_score\", 0) or 0)\n    flagged_rate = float(risk_summary.get(\"flagged_message_rate\", 0) or 0)\n    repeat_flags = sum(1 for e in prior_events if e.get(\"event_type\") == \"drift_flagged\")\n\n    if avg_drift >= DRIFT_Z_THRESHOLD * 1.2 or flagged_rate > 0.15 or repeat_flags >= 3:\n        return {\n            \"action\": \"escalate_for_manual_review\",\n            \"rationale\": (\n                f\"Average drift score {avg_drift:.2f} and/or flagged-message rate \"\n                f\"{flagged_rate*100:.1f}% exceed the escalation thresholds, with \"\n                f\"{repeat_flags} prior drift-flag event(s) on record for this \"\n                \"pseudonym. Rule-based fallback (watsonx.ai not consulted).\"\n            ),\n        }\n    if avg_drift >= DRIFT_Z_THRESHOLD:\n        return {\n            \"action\": \"continue_monitoring\",\n            \"rationale\": (\n                f\"Average drift score {avg_drift:.2f} is above the flagging \"\n                f\"threshold ({DRIFT_Z_THRESHOLD}) but below the escalation bar. \"\n                \"Rule-based fallback (watsonx.ai not consulted).\"\n            ),\n        }\n    return {\n        \"action\": \"no_action_needed\",\n        \"rationale\": (\n            f\"Average drift score {avg_drift:.2f} is within this user's own \"\n            \"normal range. Rule-based fallback (watsonx.ai not consulted).\"\n        ),\n    }\n\n\ndef _llm_recommendation(pseudonym: str, risk_summary: dict, messages: list,\n                         prior_events: list, explanation: Optional[str]) -> Optional[dict]:\n    \"\"\"Asks watsonx.ai to reason over *all* evidence gathered so far and\n    propose one of the fixed ACTIONS. Unlike explain_drift() (a one-shot\n    call on the summary row alone), this is the agent's synthesis step —\n    it sees the recent-message trend and the prior-audit history too.\n    Returns None (triggering the rule-based fallback) if watsonx isn't\n    configured or its response can't be parsed into a known action.\"\"\"\n    model = _get_model()\n    if model is None:\n        return None\n\n    prompt = (\n        \"You are an insider-risk investigation agent assisting a human security \"\n        \"analyst. You may only recommend one of exactly three actions — you have \"\n        \"no ability to take action yourself, only to recommend. Choose the single \"\n        \"best action and justify it in 2-3 sentences using only the evidence \"\n        \"given. Never claim certainty about intent or wrongdoing; this is a \"\n        \"statistical signal for human review only.\\n\\n\"\n        f\"Pseudonymous user: {pseudonym}\\n\"\n        f\"Risk summary: {risk_summary}\\n\"\n        f\"Recent scored messages (most recent {len(messages)}): {messages}\\n\"\n        f\"Prior audit events for this user: {len(prior_events)} on record\\n\"\n        f\"Existing plain-language explanation: {explanation or 'none available'}\\n\\n\"\n        \"Respond in EXACTLY this format:\\n\"\n        \"ACTION: <escalate_for_manual_review|continue_monitoring|no_action_needed>\\n\"\n        \"RATIONALE: <2-3 sentences>\"\n    )\n    try:\n        raw = model.generate_text(prompt=prompt)\n        text = raw.strip() if isinstance(raw, str) else str(raw)\n    except Exception as e:\n        logger.error(f\"watsonx.ai call failed during agent synthesis: {e}\")\n        return None\n\n    action = next((a for a in ACTIONS if a in text), None)\n    if action is None:\n        return None\n    rationale = text.split(\"RATIONALE:\", 1)[-1].strip() if \"RATIONALE:\" in text else text\n    return {\"action\": action, \"rationale\": rationale, \"raw_model_output\": text}\n\n\n# ---------------------------------------------------------------------------\n# Agent entry point\n# ---------------------------------------------------------------------------\n\ndef investigate_user(pseudonym: str, actor: str = \"system\") -> dict:\n    \"\"\"\n    Runs the full plan-act-observe loop for one pseudonym and returns a\n    structured, auditable investigation report. Safe to call repeatedly —\n    it never mutates risk data, consent state, or the audit chain beyond\n    appending its own trace entries.\n    \"\"\"\n    trace = []\n\n    risk_summary = _tool_get_risk_summary(pseudonym)\n    trace.append({\"tool\": \"get_risk_summary\", \"found\": risk_summary is not None})\n    if risk_summary is None:\n        return {\n            \"user_pseudonym\": pseudonym,\n            \"generated_by\": AGENT_VERSION,\n            \"error\": f\"No risk data for pseudonym '{pseudonym}'. Has the pipeline been run?\",\n            \"evidence_trace\": trace,\n            \"requires_human_review\": True,\n        }\n\n    messages = _tool_get_recent_messages(pseudonym)\n    trace.append({\"tool\": \"get_recent_messages\", \"count\": len(messages)})\n\n    prior_events = _tool_get_prior_audit_events(pseudonym)\n    trace.append({\"tool\": \"get_prior_audit_events\", \"count\": len(prior_events)})\n\n    explanation = explain_drift(pseudonym, risk_summary)\n    trace.append({\"tool\": \"get_watsonx_explanation\", \"available\": explanation is not None})\n\n    # Only spend a retrieval + reasoning step on governance docs when the\n    # evidence so far is actually borderline enough to warrant it — keeps\n    # low-risk users cheap to investigate.\n    policy_context = []\n    avg_drift = float(risk_summary.get(\"avg_drift_score\", 0) or 0)\n    if avg_drift >= DRIFT_Z_THRESHOLD:\n        policy_context = _tool_search_governance_docs(\n            \"insider risk escalation review consent audit process\"\n        )\n        trace.append({\"tool\": \"search_governance_docs\", \"hits\": len(policy_context)})\n\n    recommendation = _llm_recommendation(pseudonym, risk_summary, messages, prior_events, explanation)\n    used_llm = recommendation is not None\n    if recommendation is None:\n        recommendation = _rule_based_recommendation(risk_summary, prior_events)\n    trace.append({\"tool\": \"synthesize_recommendation\", \"used_watsonx\": used_llm})\n\n    report = {\n        \"user_pseudonym\": pseudonym,\n        \"generated_by\": AGENT_VERSION,\n        \"watsonx_reasoning_used\": used_llm,\n        \"watsonx_configured\": WATSONX_ENABLED,\n        \"risk_summary\": risk_summary,\n        \"explanation\": explanation,\n        \"policy_context\": policy_context,\n        \"recommendation\": recommendation[\"action\"],\n        \"rationale\": recommendation[\"rationale\"],\n        \"evidence_trace\": trace,\n        # Hard-coded, not model-controllable: the agent proposes, a human\n        # analyst/admin disposes. See module docstring guardrail (2).\n        \"requires_human_review\": True,\n    }\n\n    log_event(\n        \"agent_investigation_completed\",\n        pseudonym,\n        {\n            \"recommendation\": recommendation[\"action\"],\n            \"watsonx_reasoning_used\": used_llm,\n            \"steps\": len(trace),\n        },\n        actor=actor,\n    )\n    return report\n\n\nif __name__ == \"__main__\":\n    import json\n    import sys\n    target = sys.argv[1] if len(sys.argv) > 1 else \"emp_abc123\"\n    print(json.dumps(investigate_user(target), indent=2, default=str))"}, {"title": "FastAPI app", "path": "Suhani_PBEL_3.0-main 2/Suhani_PBEL_3.0-main/source code/src/api/app.py", "code": "\"\"\"\nPART 2 — FastAPI entrypoint.\n\nRun locally with:\n    uvicorn src.api.app:app --reload --host 0.0.0.0 --port 8000\n\nServes both the JSON API (mounted routers) and the static frontend\ndashboard (frontend/) so the whole thing is one deployable unit — matches\nthe IBM Code Engine deployment target (single container).\n\"\"\"\nimport logging\nfrom pathlib import Path\n\nfrom fastapi import FastAPI\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom fastapi.staticfiles import StaticFiles\n\nfrom src.config import ROOT_DIR\nfrom src.api.routes import users, drift, assistant, governance, agent\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\napp = FastAPI(\n    title=\"Insider Threat NLP — Behavioral Drift Detection API\",\n    description=(\n        \"Detects linguistic/behavioral drift in internal communications as a \"\n        \"privacy-respecting insider-risk signal. All user-facing data is \"\n        \"pseudonymous by design — see docs/ETHICS_AND_PRIVACY.md.\"\n    ),\n    version=\"0.1.0\",\n)\n\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=[\"*\"],  # tighten in production to the actual frontend origin\n    allow_methods=[\"*\"],\n    allow_headers=[\"*\"],\n)\n\napp.include_router(users.router, prefix=\"/api/users\", tags=[\"users\"])\napp.include_router(drift.router, prefix=\"/api/drift\", tags=[\"drift\"])\napp.include_router(assistant.router, prefix=\"/api/assistant\", tags=[\"watsonx-assistant\"])\napp.include_router(governance.router, prefix=\"/api/governance\", tags=[\"governance\"])\napp.include_router(agent.router, prefix=\"/api/agent\", tags=[\"agentic-ai\"])\n\n\n@app.get(\"/health\")\ndef health():\n    return {\"status\": \"ok\"}\n\n\n# Mounted LAST and at \"/\": StaticFiles(html=True) greedily serves \"/\" and any\n# unmatched path as index.html, so it must be registered after every API\n# route (and after /health) to avoid shadowing them.\nFRONTEND_DIR = ROOT_DIR / \"frontend\"\nif FRONTEND_DIR.exists():\n    app.mount(\"/\", StaticFiles(directory=str(FRONTEND_DIR), html=True), name=\"frontend\")\n"}, {"title": "Tamper-evident audit log", "path": "Suhani_PBEL_3.0-main 2/Suhani_PBEL_3.0-main/source code/src/governance/audit_log.py", "code": "\"\"\"\nPART 2 — Audit logging (watsonx.governance-style).\n\nEvery scoring decision, drift flag, and watsonx.ai call that touches a\nreal (pseudonymized) user should leave an append-only, tamper-evident\ntrail — this is the \"responsibly audit/limit this\" requirement from the\nmentor's notes made concrete.\n\nDesign: JSON Lines file, each entry hash-chained to the previous one\n(entry.prev_hash = hash of previous entry), so any retroactive edit or\ndeletion breaks the chain and is detectable by verify_chain(). This is\nthe same core idea as a blockchain's tamper-evidence, applied to a single\nappend-only log rather than a distributed ledger — appropriate here since\nwe don't need consensus, just detectability.\n\nIn a real IBM Cloud deployment this would write to a governed store\n(e.g. watsonx.governance's own audit trail, or an immutable Cloud Object\nStorage bucket with retention lock) instead of a local file — swap\n_append() to do that without touching call sites.\n\"\"\"\nimport json\nimport hashlib\nimport logging\nimport os\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Optional\n\nfrom src.config import AUDIT_LOG_PATH\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n\ndef _resolve_writable_log_path(preferred: Path) -> Path:\n    \"\"\"\n    Serverless deploy targets (Vercel's Python runtime among them) ship the\n    function bundle as a read-only filesystem — only /tmp is writable, and\n    /tmp is ephemeral per invocation/container. `preferred` (the real\n    ROOT_DIR-relative path, fine for local dev / a real container deploy\n    like IBM Code Engine) is used when its parent directory is actually\n    writable; otherwise we fall back to /tmp so log_event() below can\n    always succeed rather than throwing OSError/PermissionError straight\n    through every route that calls it (that was crashing\n    /api/drift/messages and /api/drift/explain with 500s on Vercel,\n    unrelated to watsonx).\n    \"\"\"\n    try:\n        preferred.parent.mkdir(parents=True, exist_ok=True)\n        probe = preferred.parent / \".write_test\"\n        with open(probe, \"w\") as f:\n            f.write(\"ok\")\n        probe.unlink(missing_ok=True)\n        return preferred\n    except OSError:\n        fallback = Path(\"/tmp\") / preferred.name\n        logger.warning(\n            f\"Audit log path {preferred} is not writable in this environment \"\n            f\"(read-only filesystem, e.g. Vercel serverless) — falling back to \"\n            f\"{fallback}. Note: /tmp is ephemeral, so this fallback log does not \"\n            f\"persist across deployments/cold starts. For a durable audit trail \"\n            f\"in serverless, point AUDIT_LOG_PATH at external storage instead.\"\n        )\n        return fallback\n\n\nAUDIT_LOG_PATH = _resolve_writable_log_path(AUDIT_LOG_PATH)\n\n\ndef _hash_entry(entry: dict) -> str:\n    payload = json.dumps(entry, sort_keys=True, default=str).encode(\"utf-8\")\n    return hashlib.sha256(payload).hexdigest()\n\n\ndef _last_hash() -> str:\n    if not AUDIT_LOG_PATH.exists() or AUDIT_LOG_PATH.stat().st_size == 0:\n        return \"0\" * 64  # genesis\n    with open(AUDIT_LOG_PATH, \"rb\") as f:\n        last_line = None\n        for line in f:\n            if line.strip():\n                last_line = line\n    if last_line is None:\n        return \"0\" * 64\n    return json.loads(last_line)[\"entry_hash\"]\n\n\ndef log_event(event_type: str, user_pseudonym: Optional[str], details: dict,\n              actor: str = \"system\") -> dict:\n    \"\"\"\n    event_type examples: 'drift_flagged', 'watsonx_explanation_generated',\n    'model_prediction', 'consent_revoked', 'api_access'\n    \"\"\"\n    entry = {\n        \"timestamp\": datetime.now(timezone.utc).isoformat(),\n        \"event_type\": event_type,\n        \"user_pseudonym\": user_pseudonym,  # NEVER a real username — pseudonyms only\n        \"actor\": actor,\n        \"details\": details,\n        \"prev_hash\": _last_hash(),\n    }\n    entry[\"entry_hash\"] = _hash_entry(entry)\n\n    try:\n        with open(AUDIT_LOG_PATH, \"a\") as f:\n            f.write(json.dumps(entry, default=str) + \"\\n\")\n    except OSError as e:\n        # Audit logging is important but must never be able to take down the\n        # feature it's logging (drift lookup, explanation, etc.) — a route\n        # returning data to an analyst shouldn't 500 just because the append\n        # failed. Log loudly server-side instead so the gap is visible.\n        logger.error(f\"Failed to write audit log entry ({event_type}): {e}\")\n\n    return entry\n\n\ndef verify_chain() -> bool:\n    \"\"\"Walk the whole log and confirm each entry's prev_hash matches the prior entry's hash.\"\"\"\n    if not AUDIT_LOG_PATH.exists():\n        return True\n\n    expected_prev = \"0\" * 64\n    with open(AUDIT_LOG_PATH, \"r\") as f:\n        for i, line in enumerate(f):\n            if not line.strip():\n                continue\n            entry = json.loads(line)\n            if entry[\"prev_hash\"] != expected_prev:\n                logger.error(f\"Audit chain broken at line {i}: prev_hash mismatch.\")\n                return False\n            claimed_hash = entry.pop(\"entry_hash\")\n            recomputed = _hash_entry(entry)\n            if claimed_hash != recomputed:\n                logger.error(f\"Audit chain broken at line {i}: entry_hash mismatch (tampered content).\")\n                return False\n            expected_prev = claimed_hash\n    logger.info(\"Audit chain verified OK.\")\n    return True\n\n\ndef get_recent_entries(n: int = 20) -> list:\n    \"\"\"\n    Return the most recent `n` log entries (oldest to newest), each with its\n    'entry_hash'/'prev_hash' bookkeeping fields intact. Used by `signal audit\n    tail` (src/api CLI) and by src/governance/rag.py, which folds recent\n    entries into its retrieval corpus so an analyst can ask natural-language\n    questions like \"was anything unusual logged recently?\" and get an answer\n    grounded in the real audit trail, not just the static docs.\n    \"\"\"\n    if not AUDIT_LOG_PATH.exists():\n        return []\n    with open(AUDIT_LOG_PATH, \"r\") as f:\n        lines = [line for line in f if line.strip()]\n    return [json.loads(line) for line in lines[-n:]]\n\n\nif __name__ == \"__main__\":\n    log_event(\"drift_flagged\", \"emp_abc123\", {\"drift_score\": 3.2, \"flagged_features\": [\"urgency_score\"]})\n    log_event(\"model_prediction\", \"emp_abc123\", {\"model\": \"random_forest\", \"risk_proba\": 0.81})\n    print(\"Chain valid:\", verify_chain())\n    print(\"Recent entries:\", get_recent_entries(n=5))\n"}, {"title": "Consent gate", "path": "Suhani_PBEL_3.0-main 2/Suhani_PBEL_3.0-main/source code/src/governance/consent.py", "code": "\"\"\"\nPART 1 — Consent gating.\n\nThis is the \"privacy-by-design\" piece the mentor's notes flagged as the\ndifferentiator: linguistic drift analysis on employee communications is\nsensitive, so nothing downstream (features, baselines, drift scoring)\nshould run for a user without a recorded, current consent record.\n\nDesign: a simple CSV-backed consent ledger (data/interim/consent.csv) with\ncolumns [user, consented, consented_on, scope]. In production this would\nbe backed by an actual HR/legal system of record — this module just\ndefines the *interface* the rest of the pipeline depends on, so swapping\nthe backing store later doesn't touch feature/model code.\n\"\"\"\nimport logging\nfrom pathlib import Path\nfrom typing import Set\n\nimport pandas as pd\n\nfrom src.config import DATA_INTERIM, CONSENT_REQUIRED\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\nCONSENT_PATH = DATA_INTERIM / \"consent.csv\"\n\n\ndef ensure_consent_ledger(all_users: Set[str]) -> None:\n    \"\"\"\n    Create a default consent ledger if one doesn't exist yet. Defaults\n    everyone to consented=True ONLY for local dev/demo purposes — in a\n    real deployment this file must come from an actual consent system,\n    never be auto-generated as \"opt-in by default.\"\n    \"\"\"\n    if CONSENT_PATH.exists():\n        return\n    logger.warning(\n        \"No consent.csv found — generating a DEV-ONLY default ledger with \"\n        \"all users opted in. Replace this with a real consent system of \"\n        \"record before using on real employee data.\"\n    )\n    df = pd.DataFrame({\n        \"user\": sorted(all_users),\n        \"consented\": True,\n        \"consented_on\": pd.Timestamp.now().strftime(\"%Y-%m-%d\"),\n        \"scope\": \"linguistic_drift_analysis_v1\",\n    })\n    df.to_csv(CONSENT_PATH, index=False)\n\n\ndef get_consented_users() -> Set[str]:\n    if not CONSENT_REQUIRED:\n        return set()  # sentinel: caller should treat \"consent not required\" specially\n    if not CONSENT_PATH.exists():\n        return set()\n    df = pd.read_csv(CONSENT_PATH)\n    return set(df.loc[df[\"consented\"] == True, \"user\"])  # noqa: E712\n\n\ndef filter_to_consented(df: pd.DataFrame, user_col: str = \"user\") -> pd.DataFrame:\n    \"\"\"Drop rows for any user without an active consent record. No-op if CONSENT_REQUIRED=False.\"\"\"\n    if not CONSENT_REQUIRED:\n        return df\n\n    ensure_consent_ledger(set(df[user_col].unique()))\n    consented = get_consented_users()\n    before = len(df)\n    filtered = df[df[user_col].isin(consented)].copy()\n    dropped = before - len(filtered)\n    if dropped:\n        logger.info(f\"Consent gate: dropped {dropped}/{before} rows for non-consented users.\")\n    return filtered\n\n\ndef revoke_consent(user: str) -> None:\n    \"\"\"Mark a user as no longer consented. Downstream jobs should re-check before their next run.\"\"\"\n    if not CONSENT_PATH.exists():\n        return\n    df = pd.read_csv(CONSENT_PATH)\n    df.loc[df[\"user\"] == user, \"consented\"] = False\n    df.to_csv(CONSENT_PATH, index=False)\n    logger.info(f\"Consent revoked for user={user}\")\n"}], "transaction": [{"title": "FastAPI scoring engine", "path": "transaction-anomaly-notifier-main/transaction-anomaly-notifier-main/main.py", "code": "from fastapi import FastAPI, HTTPException\nfrom pydantic import BaseModel, Field\nfrom typing import Optional, List\nimport pandas as pd\nimport psycopg2\nimport psycopg2.extras\nimport os\nimport logging\nfrom datetime import datetime\n\n# ─── Logging ─────────────────────────────────────────────────────────────────\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n# ─── App ─────────────────────────────────────────────────────────────────────\napp = FastAPI(\n    title=\"Fraud Detection API\",\n    description=\"Real-time fraud detection with rule-based alerting and audit logging\",\n    version=\"2.0.0\",\n    # Swagger UI is available at /docs  ← this is the default, no extra config needed\n)\n\n# ─── Load & compute baseline stats ───────────────────────────────────────────\ndf = pd.read_csv(\"transactions.csv\")\nmean_amount = df[\"amount\"].mean()\nstd_amount = df[\"amount\"].std()\nmean_time_gap = df[\"time_gap_minutes\"].mean()\n\n# ─── DB helpers ──────────────────────────────────────────────────────────────\ndef get_db():\n    \"\"\"Create a PostgreSQL connection. Yields connection, closes after use.\"\"\"\n    conn = psycopg2.connect(\n        host=os.getenv(\"DB_HOST\", \"localhost\"),\n        port=os.getenv(\"DB_PORT\", 5432),\n        dbname=os.getenv(\"DB_NAME\", \"fraud_db\"),\n        user=os.getenv(\"DB_USER\", \"postgres\"),\n        password=os.getenv(\"DB_PASSWORD\", \"password\"),\n    )\n    try:\n        yield conn\n    finally:\n        conn.close()\n\n\ndef create_audit_table(conn):\n    \"\"\"Create audit_logs table with indexes if it doesn't exist yet.\"\"\"\n    with conn.cursor() as cur:\n        cur.execute(\"\"\"\n            CREATE TABLE IF NOT EXISTS audit_logs (\n                id               SERIAL PRIMARY KEY,\n                transaction_id   TEXT,\n                amount           FLOAT,\n                time_gap_minutes FLOAT,\n                location         TEXT,\n                device           TEXT,\n                z_score          FLOAT,\n                risk_score       INT,\n                status           TEXT,\n                confidence       FLOAT,\n                alert_triggered  BOOLEAN,\n                alert_reason     TEXT,\n                created_at       TIMESTAMP DEFAULT NOW()\n            );\n            CREATE INDEX IF NOT EXISTS idx_audit_status\n                ON audit_logs(status);\n            CREATE INDEX IF NOT EXISTS idx_audit_created_at\n                ON audit_logs(created_at);\n            CREATE INDEX IF NOT EXISTS idx_audit_transaction_id\n                ON audit_logs(transaction_id);\n        \"\"\")\n    conn.commit()\n\n\n# ─── Pydantic models ─────────────────────────────────────────────────────────\n\nclass TransactionInput(BaseModel):\n    transaction_id: Optional[str] = None\n    amount: float\n    time_gap_minutes: Optional[float] = None\n    # NEW: location and device fields\n    location: Optional[str] = \"Unknown\"   # e.g. \"Delhi\", \"Mumbai\", \"International\"\n    device: Optional[str] = \"mobile\"      # e.g. \"mobile\", \"desktop\", \"new_device\", \"pos\"\n\n\nclass PredictionResponse(BaseModel):\n    transaction_id: Optional[str]\n    amount: float\n    location: Optional[str]\n    device: Optional[str]\n    z_score: float\n    risk_score: int          # 0–100\n    confidence: float        # 0.0–1.0  ← NEW\n    status: str              # NORMAL | SUSPICIOUS | HIGH_RISK\n    alert_triggered: bool\n    alert_reason: Optional[str]\n    recommendation: str\n\n\n# ─── Rule-based alerting engine ──────────────────────────────────────────────\n\ndef compute_risk(\n    amount: float,\n    time_gap_minutes: Optional[float] = None,\n    location: Optional[str] = \"Unknown\",\n    device: Optional[str] = \"mobile\",\n) -> dict:\n    \"\"\"\n    Multi-factor rule engine.\n    Rules:\n      1. Z-score (statistical outlier)\n      2. Absolute value threshold\n      3. Velocity (time since last transaction)\n      4. Location risk          ← NEW\n      5. Device risk            ← NEW\n\n    Returns z_score, risk_score (0-100), confidence, status, alert flag, reason.\n    \"\"\"\n    z_score = (amount - mean_amount) / std_amount\n    risk_score = 0\n    reasons = []\n\n    # ── Rule 1: statistical outlier ──────────────────────────────────────────\n    if abs(z_score) > 3.0:\n        risk_score += 50\n        reasons.append(f\"extreme z-score ({z_score:.2f})\")\n    elif abs(z_score) > 2.0:\n        risk_score += 30\n        reasons.append(f\"high z-score ({z_score:.2f})\")\n    elif abs(z_score) > 1.5:\n        risk_score += 15\n        reasons.append(f\"elevated z-score ({z_score:.2f})\")\n\n    # ── Rule 2: absolute high-value threshold ────────────────────────────────\n    if amount > 10_000:\n        risk_score += 25\n        reasons.append(\"amount exceeds ₹10,000\")\n    elif amount > 5_000:\n        risk_score += 10\n        reasons.append(\"amount exceeds ₹5,000\")\n\n    # ── Rule 3: velocity check ───────────────────────────────────────────────\n    if time_gap_minutes is not None:\n        if time_gap_minutes < 1:\n            risk_score += 25\n            reasons.append(f\"rapid succession ({time_gap_minutes:.1f} min gap)\")\n        elif time_gap_minutes < mean_time_gap * 0.3:\n            risk_score += 10\n            reasons.append(f\"below-average time gap ({time_gap_minutes:.1f} min)\")\n\n    # ── Rule 4: location risk (NEW) ──────────────────────────────────────────\n    if location:\n        loc = location.strip().lower()\n        if loc in [\"unknown\", \"\"]:\n            risk_score += 20\n            reasons.append(\"unknown location detected\")\n        elif loc == \"international\":\n            risk_score += 15\n            reasons.append(\"international transaction flagged\")\n\n    # ── Rule 5: device risk (NEW) ────────────────────────────────────────────\n    if device:\n        dev = device.strip().lower()\n        if dev == \"new_device\":\n            risk_score += 15\n            reasons.append(\"new or unrecognized device\")\n\n    # ── Clamp & classify ─────────────────────────────────────────────────────\n    risk_score = min(risk_score, 100)\n\n    if risk_score >= 60:\n        status = \"HIGH_RISK\"\n    elif risk_score >= 30:\n        status = \"SUSPICIOUS\"\n    else:\n        status = \"NORMAL\"\n\n    # ── Confidence score (NEW) ───────────────────────────────────────────────\n    # More rules fired = higher confidence in the prediction\n    rule_count = len(reasons)\n    if status == \"HIGH_RISK\":\n        confidence = min(0.70 + (rule_count * 0.06), 0.99)\n    elif status == \"SUSPICIOUS\":\n        confidence = min(0.55 + (rule_count * 0.05), 0.85)\n    else:\n        confidence = max(0.90 - (rule_count * 0.05), 0.70)\n\n    confidence = round(confidence, 2)\n\n    # Alert fires when risk is high enough OR multiple rules triggered together\n    alert_triggered = risk_score >= 60 or (risk_score >= 30 and len(reasons) >= 2)\n    alert_reason = \"; \".join(reasons) if reasons else None\n\n    recommendations = {\n        \"HIGH_RISK\":  \"Block transaction and notify compliance team immediately.\",\n        \"SUSPICIOUS\": \"Flag for manual review before processing.\",\n        \"NORMAL\":     \"Approve transaction.\",\n    }\n\n    return {\n        \"z_score\":         round(z_score, 4),\n        \"risk_score\":      risk_score,\n        \"confidence\":      confidence,\n        \"status\":          status,\n        \"alert_triggered\": alert_triggered,\n        \"alert_reason\":    alert_reason,\n        \"recommendation\":  recommendations[status],\n    }\n\n\n# ─── Endpoints ───────────────────────────────────────────────────────────────\n\n@app.get(\"/\")\ndef root():\n    return {\n        \"service\": \"Fraud Detection API\",\n        \"version\": \"2.0.0\",\n        \"status\":  \"running\",\n        \"docs\":    \"/docs\",        # ← tells people where Swagger UI is\n        \"health\":  \"/health\",\n    }\n\n\n@app.get(\"/health\")\ndef health():\n    return {\"status\": \"ok\", \"timestamp\": datetime.utcnow().isoformat()}\n\n\n@app.post(\"/predict\", response_model=PredictionResponse)\ndef predict(txn: TransactionInput):\n    \"\"\"\n    Score a single transaction for fraud risk.\n\n    **Example request body:**\n    ```json\n    {\n      \"transaction_id\": \"txn_001\",\n      \"amount\": 14500,\n      \"time_gap_minutes\": 0.3,\n      \"location\": \"International\",\n      \"device\": \"new_device\"\n    }\n    ```\n\n    **Example response:**\n    ```json\n    {\n      \"status\": \"HIGH_RISK\",\n      \"risk_score\": 85,\n      \"confidence\": 0.88,\n      \"alert_triggered\": true\n    }\n    ```\n    \"\"\"\n    result = compute_risk(\n        txn.amount,\n        txn.time_gap_minutes,\n        txn.location,\n        txn.device,\n    )\n\n    # ── Attempt DB write (non-fatal: API still responds if DB is down) ────────\n    try:\n        conn = psycopg2.connect(\n            host=os.getenv(\"DB_HOST\", \"localhost\"),\n            port=os.getenv(\"DB_PORT\", 5432),\n            dbname=os.getenv(\"DB_NAME\", \"fraud_db\"),\n            user=os.getenv(\"DB_USER\", \"postgres\"),\n            password=os.getenv(\"DB_PASSWORD\", \"password\"),\n        )\n        create_audit_table(conn)\n        with conn.cursor() as cur:\n            cur.execute(\n                \"\"\"\n                INSERT INTO audit_logs\n                    (transaction_id, amount, time_gap_minutes, location, device,\n                     z_score, risk_score, confidence, status, alert_triggered, alert_reason)\n                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)\n                \"\"\",\n                (\n                    txn.transaction_id,\n                    txn.amount,\n                    txn.time_gap_minutes,\n                    txn.location,\n                    txn.device,\n                    result[\"z_score\"],\n                    result[\"risk_score\"],\n                    result[\"confidence\"],\n                    result[\"status\"],\n                    result[\"alert_triggered\"],\n                    result[\"alert_reason\"],\n                ),\n            )\n        conn.commit()\n        conn.close()\n        logger.info(f\"Audit log written for transaction {txn.transaction_id}\")\n    except Exception as e:\n        logger.warning(f\"DB write skipped (DB may be offline): {e}\")\n\n    return PredictionResponse(\n        transaction_id=txn.transaction_id,\n        amount=txn.amount,\n        location=txn.location,\n        device=txn.device,\n        **result,\n    )\n\n\n# ─── Batch predict ────────────────────────────────────────────────────────────\n\nclass BatchInput(BaseModel):\n    transactions: List[TransactionInput] = Field(..., max_length=100)\n\n\n@app.post(\"/batch-predict\")\ndef batch_predict(batch: BatchInput):\n    \"\"\"\n    Score up to 100 transactions in one request.\n    Returns per-transaction results plus an aggregate summary.\n\n    **Example request body:**\n    ```json\n    {\n      \"transactions\": [\n        {\"transaction_id\": \"t1\", \"amount\": 200, \"time_gap_minutes\": 30, \"location\": \"Delhi\", \"device\": \"mobile\"},\n        {\"transaction_id\": \"t2\", \"amount\": 99000, \"time_gap_minutes\": 0.1, \"location\": \"International\", \"device\": \"new_device\"}\n      ]\n    }\n    ```\n    \"\"\"\n    if not batch.transactions:\n        raise HTTPException(status_code=400, detail=\"Transaction list cannot be empty.\")\n\n    results = []\n    for txn in batch.transactions:\n        risk = compute_risk(txn.amount, txn.time_gap_minutes, txn.location, txn.device)\n        results.append({\n            \"transaction_id\": txn.transaction_id,\n            \"amount\":         txn.amount,\n            \"location\":       txn.location,\n            \"device\":         txn.device,\n            **risk,\n        })\n\n    high_risk_count  = sum(1 for r in results if r[\"status\"] == \"HIGH_RISK\")\n    suspicious_count = sum(1 for r in results if r[\"status\"] == \"SUSPICIOUS\")\n    normal_count     = sum(1 for r in results if r[\"status\"] == \"NORMAL\")\n    avg_risk         = round(sum(r[\"risk_score\"] for r in results) / len(results), 2)\n\n    return {\n        \"count\":   len(results),\n        \"results\": results,\n        \"summary\": {\n            \"high_risk_count\":  high_risk_count,\n            \"suspicious_count\": suspicious_count,\n            \"normal_count\":     normal_count,\n            \"avg_risk_score\":   avg_risk,\n            \"alert_rate_pct\":   round(\n                (high_risk_count + suspicious_count) / len(results) * 100, 1\n            ),\n        },\n    }\n\n\n# ─── Audit logs ──────────────────────────────────────────────────────────────\n\n@app.get(\"/audit-logs\")\ndef get_audit_logs(status: Optional[str] = None, limit: int = 50):\n    \"\"\"\n    Retrieve recent audit logs from PostgreSQL.\n    Optionally filter by status: NORMAL | SUSPICIOUS | HIGH_RISK\n    \"\"\"\n    try:\n        conn = psycopg2.connect(\n            host=os.getenv(\"DB_HOST\", \"localhost\"),\n            port=os.getenv(\"DB_PORT\", 5432),\n            dbname=os.getenv(\"DB_NAME\", \"fraud_db\"),\n            user=os.getenv(\"DB_USER\", \"postgres\"),\n            password=os.getenv(\"DB_PASSWORD\", \"password\"),\n        )\n        create_audit_table(conn)\n        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:\n            if status:\n                cur.execute(\n                    \"SELECT * FROM audit_logs WHERE status = %s \"\n                    \"ORDER BY created_at DESC LIMIT %s\",\n                    (status.upper(), limit),\n                )\n            else:\n                cur.execute(\n                    \"SELECT * FROM audit_logs ORDER BY created_at DESC LIMIT %s\",\n                    (limit,),\n                )\n            rows = cur.fetchall()\n        conn.close()\n        return {\"count\": len(rows), \"logs\": rows}\n    except Exception as e:\n        raise HTTPException(status_code=503, detail=f\"Database unavailable: {e}\")\n"}, {"title": "AWS Lambda handler", "path": "transaction-anomaly-notifier-main/transaction-anomaly-notifier-main/lambda_handler.py", "code": "\"\"\"\nlambda_handler.py\n─────────────────\nAWS Lambda entry point. API Gateway routes POST /predict to this function.\n\nDeploy steps (quick reference — see README for full walkthrough):\n  1. zip -r function.zip . (from inside fraud_detection_api/)\n  2. Upload to Lambda in AWS Console\n  3. Set environment variables (DB_HOST, DB_NAME, DB_USER, DB_PASSWORD)\n  4. Attach API Gateway trigger with route POST /predict\n\"\"\"\n\nimport json\nimport pandas as pd\n\n# ── Load baseline stats once (Lambda keeps the container warm between calls) ──\ndf = pd.read_csv(\"transactions.csv\")\nmean_amount = df[\"amount\"].mean()\nstd_amount = df[\"amount\"].std()\nmean_time_gap = df[\"time_gap_minutes\"].mean()\n\n\ndef compute_risk(amount: float, time_gap_minutes=None) -> dict:\n    \"\"\"Identical rule engine to main.py — kept in sync manually.\"\"\"\n    z_score = (amount - mean_amount) / std_amount\n    risk_score = 0\n    reasons = []\n\n    if abs(z_score) > 3.0:\n        risk_score += 50\n        reasons.append(f\"extreme z-score ({z_score:.2f})\")\n    elif abs(z_score) > 2.0:\n        risk_score += 30\n        reasons.append(f\"high z-score ({z_score:.2f})\")\n    elif abs(z_score) > 1.5:\n        risk_score += 15\n        reasons.append(f\"elevated z-score ({z_score:.2f})\")\n\n    if amount > 10_000:\n        risk_score += 25\n        reasons.append(\"amount exceeds $10,000\")\n    elif amount > 5_000:\n        risk_score += 10\n        reasons.append(\"amount exceeds $5,000\")\n\n    if time_gap_minutes is not None:\n        if time_gap_minutes < 1:\n            risk_score += 25\n            reasons.append(f\"rapid succession ({time_gap_minutes:.1f} min gap)\")\n        elif time_gap_minutes < mean_time_gap * 0.3:\n            risk_score += 10\n            reasons.append(f\"below-average time gap ({time_gap_minutes:.1f} min)\")\n\n    risk_score = min(risk_score, 100)\n\n    if risk_score >= 60:\n        status = \"HIGH_RISK\"\n    elif risk_score >= 30:\n        status = \"SUSPICIOUS\"\n    else:\n        status = \"NORMAL\"\n\n    alert_triggered = risk_score >= 60 or (risk_score >= 30 and len(reasons) >= 2)\n    recommendations = {\n        \"HIGH_RISK\": \"Block transaction and notify compliance team immediately.\",\n        \"SUSPICIOUS\": \"Flag for manual review before processing.\",\n        \"NORMAL\": \"Approve transaction.\",\n    }\n\n    return {\n        \"z_score\": round(z_score, 4),\n        \"risk_score\": risk_score,\n        \"status\": status,\n        \"alert_triggered\": alert_triggered,\n        \"alert_reason\": \"; \".join(reasons) if reasons else None,\n        \"recommendation\": recommendations[status],\n    }\n\n\ndef handler(event, context):\n    \"\"\"\n    AWS Lambda handler.\n    Expects API Gateway proxy event with JSON body:\n        { \"transaction_id\": \"...\", \"amount\": 5000, \"time_gap_minutes\": 0.5 }\n    \"\"\"\n    try:\n        body = json.loads(event.get(\"body\", \"{}\"))\n        amount = float(body[\"amount\"])\n        time_gap_minutes = body.get(\"time_gap_minutes\")\n        transaction_id = body.get(\"transaction_id\")\n    except (KeyError, ValueError) as e:\n        return {\"statusCode\": 400, \"body\": json.dumps({\"error\": f\"Bad request: {e}\"})}\n\n    result = compute_risk(amount, time_gap_minutes)\n    result[\"transaction_id\"] = transaction_id\n    result[\"amount\"] = amount\n\n    return {\n        \"statusCode\": 200,\n        \"headers\": {\"Content-Type\": \"application/json\"},\n        \"body\": json.dumps(result),\n    }\n"}, {"title": "Celery alert worker", "path": "transaction-anomaly-notifier-main/transaction-anomaly-notifier-main/celery_worker.py", "code": "\"\"\"\ncelery_worker.py\n────────────────\nAsync alert dispatcher using Celery + Redis.\n\nWhen /predict flags a HIGH_RISK or SUSPICIOUS transaction, the API enqueues\na task here instead of blocking the HTTP response on slow I/O (email, Slack).\n\nArchitecture:\n    FastAPI  ──enqueue──▶  Redis (broker)  ──consume──▶  Celery worker\n                                                               │\n                                          ┌────────────────────┤\n                                          ▼                    ▼\n                                    Email (SMTP)         Slack webhook\n\nStart the worker:\n    celery -A celery_worker worker --loglevel=info --queues=alerts\n\"\"\"\n\nimport os\nimport smtplib\nimport logging\nimport requests\nfrom email.mime.text import MIMEText\nfrom celery import Celery\nfrom dotenv import load_dotenv\n\nload_dotenv()\nlogger = logging.getLogger(__name__)\n\n# ── Broker / backend ──────────────────────────────────────────────────────────\nREDIS_URL = os.getenv(\"REDIS_URL\", \"redis://localhost:6379/0\")\n\ncelery_app = Celery(\n    \"fraud_alerts\",\n    broker=REDIS_URL,\n    backend=REDIS_URL,\n)\n\ncelery_app.conf.update(\n    task_serializer=\"json\",\n    result_serializer=\"json\",\n    accept_content=[\"json\"],\n    timezone=\"Asia/Kolkata\",  # Pine Labs is based in India\n    task_routes={\"celery_worker.*\": {\"queue\": \"alerts\"}},\n    task_acks_late=True,  # re-queue if worker crashes mid-task\n    worker_prefetch_multiplier=1,  # one task at a time per worker process\n)\n\n\n# ── Email alert ───────────────────────────────────────────────────────────────\ndef _send_email(subject: str, body: str) -> bool:\n    \"\"\"\n    Send an email via SMTP.  Reads credentials from .env:\n        SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS, ALERT_EMAIL_TO\n    Returns True on success, False on failure (non-fatal).\n    \"\"\"\n    smtp_host = os.getenv(\"SMTP_HOST\")\n    smtp_port = int(os.getenv(\"SMTP_PORT\", 587))\n    smtp_user = os.getenv(\"SMTP_USER\")\n    smtp_pass = os.getenv(\"SMTP_PASS\")\n    to_addr = os.getenv(\"ALERT_EMAIL_TO\")\n\n    if not all([smtp_host, smtp_user, smtp_pass, to_addr]):\n        logger.warning(\"Email not configured — skipping email alert.\")\n        return False\n\n    msg = MIMEText(body, \"plain\")\n    msg[\"Subject\"] = subject\n    msg[\"From\"] = smtp_user\n    msg[\"To\"] = to_addr\n\n    try:\n        with smtplib.SMTP(smtp_host, smtp_port) as server:\n            server.starttls()\n            server.login(smtp_user, smtp_pass)\n            server.send_message(msg)\n        logger.info(f\"Email alert sent to {to_addr}\")\n        return True\n    except Exception as e:\n        logger.error(f\"Email send failed: {e}\")\n        return False\n\n\n# ── Slack alert ───────────────────────────────────────────────────────────────\ndef _send_slack(message: str) -> bool:\n    \"\"\"\n    Post a message to a Slack channel via Incoming Webhook.\n    Set SLACK_WEBHOOK_URL in .env.\n    \"\"\"\n    webhook_url = os.getenv(\"SLACK_WEBHOOK_URL\")\n    if not webhook_url:\n        logger.warning(\"SLACK_WEBHOOK_URL not set — skipping Slack alert.\")\n        return False\n\n    try:\n        resp = requests.post(webhook_url, json={\"text\": message}, timeout=5)\n        resp.raise_for_status()\n        logger.info(\"Slack alert sent.\")\n        return True\n    except Exception as e:\n        logger.error(f\"Slack send failed: {e}\")\n        return False\n\n\n# ── Celery task ───────────────────────────────────────────────────────────────\n@celery_app.task(\n    name=\"celery_worker.dispatch_alert\",\n    bind=True,\n    max_retries=3,\n    default_retry_delay=10,  # seconds between retries\n)\ndef dispatch_alert(\n    self,\n    transaction_id: str,\n    amount: float,\n    status: str,\n    risk_score: int,\n    alert_reason: str,\n):\n    \"\"\"\n    Async task: send email + Slack notification for flagged transactions.\n    Retried up to 3 times with exponential back-off if network errors occur.\n    \"\"\"\n    subject = f\"[FRAUD ALERT] {status} transaction detected — {transaction_id}\"\n    body = (\n        f\"Transaction ID : {transaction_id}\\n\"\n        f\"Amount         : ₹{amount:,.2f}\\n\"\n        f\"Status         : {status}\\n\"\n        f\"Risk Score     : {risk_score}/100\\n\"\n        f\"Reason         : {alert_reason}\\n\\n\"\n        f\"Please review immediately in the audit dashboard.\"\n    )\n\n    slack_msg = (\n        f\":rotating_light: *{status} ALERT* | `{transaction_id}`\\n\"\n        f\"Amount: ₹{amount:,.2f} | Risk: {risk_score}/100\\n\"\n        f\"_{alert_reason}_\"\n    )\n\n    try:\n        _send_email(subject, body)\n        _send_slack(slack_msg)\n    except Exception as exc:\n        logger.error(f\"Alert dispatch failed, retrying: {exc}\")\n        raise self.retry(exc=exc, countdown=2**self.request.retries)\n\n    return {\"sent\": True, \"transaction_id\": transaction_id}\n"}, {"title": "Pytest suite", "path": "transaction-anomaly-notifier-main/transaction-anomaly-notifier-main/tests/test_api.py", "code": "\"\"\"\ntests/test_api.py\n─────────────────\nUnit + integration tests for the Fraud Detection API.\n\nRun:\n    pytest tests/ -v --tb=short\n\nCoverage targets:\n    - Rule engine logic (z-score, velocity, high-value thresholds)\n    - /predict endpoint happy paths + edge cases\n    - /health and / endpoints\n    - DB-down graceful degradation\n    - Batch endpoint\n\"\"\"\n\nfrom fastapi.testclient import TestClient\nfrom unittest.mock import patch, MagicMock\n\n# ── Import app with DB patched out so tests don't need Postgres ───────────────\nimport sys\nimport os\n\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \"..\"))\n\nwith patch(\"psycopg2.connect\") as mock_conn:\n    mock_conn.return_value = MagicMock()\n    from main import app, compute_risk\n\nclient = TestClient(app)\n\n\n# ═══════════════════════════════════════════════════════════════════════════════\n# Helpers\n# ═══════════════════════════════════════════════════════════════════════════════\n\n\ndef predict(amount, time_gap_minutes=None, transaction_id=None):\n    payload = {\"amount\": amount}\n    if time_gap_minutes is not None:\n        payload[\"time_gap_minutes\"] = time_gap_minutes\n    if transaction_id:\n        payload[\"transaction_id\"] = transaction_id\n    return client.post(\"/predict\", json=payload)\n\n\n# ═══════════════════════════════════════════════════════════════════════════════\n# Health / root\n# ═══════════════════════════════════════════════════════════════════════════════\n\n\nclass TestHealthEndpoints:\n    def test_root_returns_200(self):\n        r = client.get(\"/\")\n        assert r.status_code == 200\n        assert r.json()[\"service\"] == \"Fraud Detection API\"\n\n    def test_health_returns_ok(self):\n        r = client.get(\"/health\")\n        assert r.status_code == 200\n        assert r.json()[\"status\"] == \"ok\"\n\n    def test_health_has_timestamp(self):\n        r = client.get(\"/health\")\n        assert \"timestamp\" in r.json()\n\n\n# ═══════════════════════════════════════════════════════════════════════════════\n# Rule engine unit tests (pure logic, no HTTP)\n# ═══════════════════════════════════════════════════════════════════════════════\n\n\nclass TestRuleEngine:\n    def test_normal_transaction_low_risk(self):\n        result = compute_risk(200, time_gap_minutes=15)\n        assert result[\"status\"] == \"NORMAL\"\n        assert result[\"risk_score\"] < 30\n        assert result[\"alert_triggered\"] is False\n\n    def test_high_amount_over_10k_adds_25(self):\n        result_10k = compute_risk(12000, time_gap_minutes=30)\n        result_5k = compute_risk(6000, time_gap_minutes=30)\n        # $12k should carry more risk than $6k\n        assert result_10k[\"risk_score\"] > result_5k[\"risk_score\"]\n\n    def test_rapid_velocity_adds_25(self):\n        result_fast = compute_risk(200, time_gap_minutes=0.5)\n        result_slow = compute_risk(200, time_gap_minutes=30)\n        assert result_fast[\"risk_score\"] > result_slow[\"risk_score\"]\n\n    def test_combined_signals_trigger_alert(self):\n        # High amount + rapid velocity → should alert\n        result = compute_risk(12000, time_gap_minutes=0.3)\n        assert result[\"alert_triggered\"] is True\n        assert result[\"status\"] in (\"SUSPICIOUS\", \"HIGH_RISK\")\n\n    def test_single_signal_below_60_no_alert(self):\n        # Only slightly elevated z-score, no other signals\n        result = compute_risk(600, time_gap_minutes=20)\n        # risk_score should be moderate but not enough for alert alone\n        if result[\"risk_score\"] < 60:\n            assert result[\"alert_triggered\"] is (\n                result[\"risk_score\"] >= 30\n                and result[\"alert_reason\"] is not None\n                and \";\" in result[\"alert_reason\"]\n            )\n\n    def test_risk_score_capped_at_100(self):\n        # Extreme transaction that would overflow without cap\n        result = compute_risk(50000, time_gap_minutes=0.1)\n        assert result[\"risk_score\"] <= 100\n\n    def test_z_score_is_float(self):\n        result = compute_risk(300)\n        assert isinstance(result[\"z_score\"], float)\n\n    def test_no_time_gap_still_scores(self):\n        result = compute_risk(500, time_gap_minutes=None)\n        assert \"risk_score\" in result\n        assert result[\"risk_score\"] >= 0\n\n    def test_alert_reason_populated_on_alert(self):\n        result = compute_risk(15000, time_gap_minutes=0.2)\n        if result[\"alert_triggered\"]:\n            assert result[\"alert_reason\"] is not None\n            assert len(result[\"alert_reason\"]) > 0\n\n    def test_recommendation_matches_status(self):\n        normal = compute_risk(200, 15)\n        suspicious = compute_risk(6000, 20)\n        high_risk = compute_risk(15000, 0.2)\n\n        assert \"Approve\" in normal[\"recommendation\"]\n        assert (\n            \"review\" in suspicious[\"recommendation\"].lower()\n            or \"Approve\" in suspicious[\"recommendation\"]\n        )\n        assert \"Block\" in high_risk[\"recommendation\"]\n\n\n# ═══════════════════════════════════════════════════════════════════════════════\n# /predict endpoint\n# ═══════════════════════════════════════════════════════════════════════════════\n\n\nclass TestPredictEndpoint:\n    def test_predict_normal_transaction(self):\n        r = predict(200, time_gap_minutes=15, transaction_id=\"txn_test_001\")\n        assert r.status_code == 200\n        body = r.json()\n        assert body[\"status\"] == \"NORMAL\"\n        assert body[\"transaction_id\"] == \"txn_test_001\"\n        assert body[\"amount\"] == 200\n\n    def test_predict_high_risk_transaction(self):\n        r = predict(20000, time_gap_minutes=0.2, transaction_id=\"txn_highrisk\")\n        assert r.status_code == 200\n        body = r.json()\n        assert body[\"status\"] == \"HIGH_RISK\"\n        assert body[\"alert_triggered\"] is True\n        assert body[\"risk_score\"] >= 60\n\n    def test_predict_missing_amount_returns_422(self):\n        r = client.post(\"/predict\", json={\"time_gap_minutes\": 5})\n        assert r.status_code == 422\n\n    def test_predict_without_time_gap(self):\n        r = predict(300)\n        assert r.status_code == 200\n        assert \"risk_score\" in r.json()\n\n    def test_predict_without_transaction_id(self):\n        r = predict(500, time_gap_minutes=10)\n        assert r.status_code == 200\n        body = r.json()\n        assert \"transaction_id\" in body  # field exists, may be None\n\n    def test_predict_response_has_all_fields(self):\n        r = predict(1000, time_gap_minutes=5, transaction_id=\"txn_fields\")\n        body = r.json()\n        expected_keys = {\n            \"transaction_id\",\n            \"amount\",\n            \"z_score\",\n            \"risk_score\",\n            \"status\",\n            \"alert_triggered\",\n            \"alert_reason\",\n            \"recommendation\",\n        }\n        assert expected_keys.issubset(body.keys())\n\n    def test_predict_zero_amount(self):\n        r = predict(0)\n        # Should succeed — 0 is a valid (unusual) amount\n        assert r.status_code == 200\n\n    def test_predict_very_large_amount(self):\n        r = predict(999999, time_gap_minutes=0.01)\n        assert r.status_code == 200\n        body = r.json()\n        assert body[\"risk_score\"] == 100\n        assert body[\"status\"] == \"HIGH_RISK\"\n\n\n# ═══════════════════════════════════════════════════════════════════════════════\n# /batch-predict endpoint\n# ═══════════════════════════════════════════════════════════════════════════════\n\n\nclass TestBatchPredict:\n    def test_batch_predict_multiple_transactions(self):\n        payload = {\n            \"transactions\": [\n                {\"transaction_id\": \"b1\", \"amount\": 200, \"time_gap_minutes\": 15},\n                {\"transaction_id\": \"b2\", \"amount\": 15000, \"time_gap_minutes\": 0.3},\n                {\"transaction_id\": \"b3\", \"amount\": 450, \"time_gap_minutes\": 30},\n            ]\n        }\n        r = client.post(\"/batch-predict\", json=payload)\n        assert r.status_code == 200\n        body = r.json()\n        assert body[\"count\"] == 3\n        assert len(body[\"results\"]) == 3\n\n    def test_batch_flags_anomalies_correctly(self):\n        payload = {\n            \"transactions\": [\n                {\"transaction_id\": \"norm\", \"amount\": 200, \"time_gap_minutes\": 20},\n                {\"transaction_id\": \"risk\", \"amount\": 18000, \"time_gap_minutes\": 0.1},\n            ]\n        }\n        r = client.post(\"/batch-predict\", json=payload)\n        results = {item[\"transaction_id\"]: item for item in r.json()[\"results\"]}\n        assert results[\"norm\"][\"status\"] == \"NORMAL\"\n        assert results[\"risk\"][\"status\"] == \"HIGH_RISK\"\n\n    def test_batch_returns_summary(self):\n        payload = {\n            \"transactions\": [\n                {\"amount\": 200},\n                {\"amount\": 200},\n                {\"amount\": 20000, \"time_gap_minutes\": 0.2},\n            ]\n        }\n        r = client.post(\"/batch-predict\", json=payload)\n        body = r.json()\n        assert \"summary\" in body\n        assert \"high_risk_count\" in body[\"summary\"]\n\n    def test_batch_empty_list_returns_400(self):\n        r = client.post(\"/batch-predict\", json={\"transactions\": []})\n        assert r.status_code == 400\n\n    def test_batch_max_100_transactions(self):\n        transactions = [{\"amount\": 200} for _ in range(101)]\n        r = client.post(\"/batch-predict\", json={\"transactions\": transactions})\n        assert r.status_code == 422  # validation error\n\n\n# ═══════════════════════════════════════════════════════════════════════════════\n# DB resilience\n# ═══════════════════════════════════════════════════════════════════════════════\n\n\nclass TestDBResilience:\n    @patch(\"psycopg2.connect\", side_effect=Exception(\"DB is down\"))\n    def test_predict_still_works_without_db(self, mock_db):\n        r = predict(300, time_gap_minutes=10, transaction_id=\"txn_nodb\")\n        # API must respond 200 even if DB is offline\n        assert r.status_code == 200\n        assert \"risk_score\" in r.json()\n"}, {"title": "GitHub Actions CI", "path": "transaction-anomaly-notifier-main/transaction-anomaly-notifier-main/.github/workflows/ci.yml", "code": "name: CI\n\non:\n  push:\n    branches: [main, develop]\n  pull_request:\n    branches: [main]\n\njobs:\n  test:\n    name: Run Tests\n    runs-on: ubuntu-latest\n\n    services:\n      postgres:\n        image: postgres:15-alpine\n        env:\n          POSTGRES_DB: fraud_db\n          POSTGRES_USER: postgres\n          POSTGRES_PASSWORD: password\n        ports:\n          - 5432:5432\n        options: >-\n          --health-cmd pg_isready\n          --health-interval 10s\n          --health-timeout 5s\n          --health-retries 5\n\n      redis:\n        image: redis:7-alpine\n        ports:\n          - 6379:6379\n\n    steps:\n      - name: Checkout code\n        uses: actions/checkout@v4\n\n      - name: Set up Python 3.11\n        uses: actions/setup-python@v5\n        with:\n          python-version: \"3.11\"\n\n      - name: Cache pip dependencies\n        uses: actions/cache@v4\n        with:\n          path: ~/.cache/pip\n          key: ${{ runner.os }}-pip-${{ hashFiles('requirements.txt') }}\n          restore-keys: |\n            ${{ runner.os }}-pip-\n\n      - name: Install dependencies\n        run: pip install -r requirements.txt\n\n      - name: Run tests with coverage\n        env:\n          DB_HOST: localhost\n          DB_PORT: 5432\n          DB_NAME: fraud_db\n          DB_USER: postgres\n          DB_PASSWORD: password\n          REDIS_URL: redis://localhost:6379/0\n        run: |\n          pip install pytest pytest-cov httpx\n          pytest tests/ -v --tb=short --cov=. --cov-report=term-missing --cov-fail-under=80\n\n      - name: Upload coverage report\n        uses: actions/upload-artifact@v4\n        with:\n          name: coverage-report\n          path: .coverage\n\n  lint:\n    name: Lint (Ruff)\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: \"3.11\"\n      - run: pip install ruff\n      - run: ruff check . --select=E,F,W --ignore=E501\n\n  docker-build:\n    name: Docker Build\n    runs-on: ubuntu-latest\n    needs: [test]\n    steps:\n      - uses: actions/checkout@v4\n      - name: Build Docker image\n        run: docker build -t fraud-detection-api:${{ github.sha }} .\n      - name: Run container smoke test\n        run: |\n          docker run -d -p 8000:8000 \\\n            -e DB_HOST=localhost \\\n            -e DB_USER=postgres \\\n            -e DB_PASSWORD=password \\\n            --name fraud_smoke \\\n            fraud-detection-api:${{ github.sha }}\n          sleep 5\n          curl -f http://localhost:8000/health || (docker logs fraud_smoke && exit 1)\n          docker stop fraud_smoke\n"}], "market": [{"title": "Fusion model", "path": "multimodal-market-signal/multimodal-market-signal/src/model.py", "code": "\"\"\"\nmodel.py\n─────────\nA multimodal fusion model with three input branches:\n\n  1. Text branch      — headline -> TextVectorization -> Embedding ->\n                         Bidirectional LSTM -> 32-d vector.\n  2. Sequence branch   — the last LOOKBACK_WINDOW daily returns ->\n                         LSTM -> 16-d vector (captures short-term momentum\n                         shape, not just a single summary stat).\n  3. Tabular branch    — same-day volume_z / volatility / rsi_like ->\n                         Dense -> 16-d vector.\n\nThe three vectors are concatenated and passed through a small classifier\nhead predicting next-day direction: {down, flat, up}.\n\nKept intentionally small (a few hundred thousand parameters, not millions)\nso it trains in seconds on CPU — the point of this project is the\nend-to-end pipeline (multimodal fusion -> distributed training ->\nquantization), not squeezing out benchmark accuracy.\n\"\"\"\n\nimport tensorflow as tf\nfrom tensorflow.keras import layers\n\nLOOKBACK_WINDOW = 10\nNUM_CLASSES = 3\n\n\ndef build_text_vectorizer(headlines, max_tokens: int = 2000, sequence_length: int = 16):\n    \"\"\"Adapt a TextVectorization layer on the training headlines.\"\"\"\n    vectorizer = layers.TextVectorization(\n        max_tokens=max_tokens,\n        output_mode=\"int\",\n        output_sequence_length=sequence_length,\n    )\n    vectorizer.adapt(headlines)\n    return vectorizer\n\n\ndef build_model(text_vectorizer: layers.TextVectorization) -> tf.keras.Model:\n    vocab_size = text_vectorizer.vocabulary_size()\n\n    # ── Text branch ───────────────────────────────────────────────────────\n    text_input = tf.keras.Input(shape=(1,), dtype=tf.string, name=\"headline\")\n    x_text = text_vectorizer(text_input)\n    x_text = layers.Embedding(vocab_size, 32, mask_zero=True)(x_text)\n    x_text = layers.Bidirectional(layers.LSTM(16))(x_text)\n    x_text = layers.Dense(32, activation=\"relu\", name=\"text_embedding\")(x_text)\n\n    # ── Return-sequence branch ───────────────────────────────────────────\n    seq_input = tf.keras.Input(shape=(LOOKBACK_WINDOW, 1), name=\"lookback_returns\")\n    x_seq = layers.LSTM(16)(seq_input)\n    x_seq = layers.Dense(16, activation=\"relu\", name=\"sequence_embedding\")(x_seq)\n\n    # ── Tabular same-day features branch ─────────────────────────────────\n    tab_input = tf.keras.Input(shape=(3,), name=\"tabular_features\")\n    x_tab = layers.Dense(16, activation=\"relu\")(tab_input)\n    x_tab = layers.Dense(16, activation=\"relu\", name=\"tabular_embedding\")(x_tab)\n\n    # ── Fusion + classifier head ─────────────────────────────────────────\n    fused = layers.Concatenate(name=\"fusion\")([x_text, x_seq, x_tab])\n    x = layers.Dense(32, activation=\"relu\")(fused)\n    x = layers.Dropout(0.2)(x)\n    output = layers.Dense(NUM_CLASSES, activation=\"softmax\", name=\"direction\")(x)\n\n    model = tf.keras.Model(\n        inputs={\n            \"headline\": text_input,\n            \"lookback_returns\": seq_input,\n            \"tabular_features\": tab_input,\n        },\n        outputs=output,\n        name=\"multimodal_market_signal\",\n    )\n    return model\n"}, {"title": "Distributed training", "path": "multimodal-market-signal/multimodal-market-signal/src/train_distributed.py", "code": "\"\"\"\ntrain_distributed.py\n──────────────────────\nTrains the multimodal fusion model using TensorFlow's native distributed\ntraining API, `tf.distribute.MirroredStrategy` (synchronous data-parallel\ntraining across all GPUs visible on one machine).\n\nWhat this demonstrates\n-------------------------\n- Wrapping model construction + compilation in `strategy.scope()`, which is\n  the part of the API that actually matters: it tells TF to create\n  variables in a way that can be mirrored across replicas.\n- Scaling batch size by `strategy.num_replicas_in_sync` (global batch size\n  = per-replica batch size x number of replicas) — a detail that's easy to\n  get wrong and skews results if missed.\n- Configuring the `tf.data` pipeline's auto-sharding policy explicitly,\n  which matters once you move to multi-worker training.\n\nHonesty note on scope\n------------------------\nThis runs on whatever hardware is available. Tested here on CPU only, so\n`strategy.num_replicas_in_sync == 1` and this executes as a single\nreplica — but the code path is unchanged from what you'd run on a\nmulti-GPU box; only the visible device count changes.\n\nFor genuine multi-node training you'd switch to\n`tf.distribute.MultiWorkerMirroredStrategy`, which needs a `TF_CONFIG`\nenvironment variable on each worker describing the cluster, e.g.:\n\n    TF_CONFIG='{\n      \"cluster\": {\"worker\": [\"host1:port\", \"host2:port\"]},\n      \"task\": {\"type\": \"worker\", \"index\": 0}\n    }'\n\nThat's the TensorFlow-native equivalent of what `torchrun` +\nFSDP/DeepSpeed config does in the PyTorch ecosystem — same goal\n(coordinate gradient sync / parameter sharding across machines),\ndifferent framework, different config surface. It is *not* the same\nmechanism as ZeRO-style parameter sharding (DeepSpeed/FSDP) or the\ntensor/pipeline model-parallelism in Megatron-LM, which split a single\nhuge model across devices rather than replicating it — this script only\ndemonstrates the data-parallel case, which is what actually applies to a\nmodel this size.\n\"\"\"\n\nimport os\n\nimport tensorflow as tf\n\nfrom src.data_pipeline import load_dataframe, make_datasets\nfrom src.model import build_model, build_text_vectorizer\n\nPER_REPLICA_BATCH_SIZE = 32\nEPOCHS = 8\nMODEL_OUT_DIR = os.path.join(os.path.dirname(__file__), \"..\", \"saved_model\")\n\n\ndef main():\n    strategy = tf.distribute.MirroredStrategy()\n    print(f\"Number of devices in sync: {strategy.num_replicas_in_sync}\")\n\n    global_batch_size = PER_REPLICA_BATCH_SIZE * strategy.num_replicas_in_sync\n\n    df = load_dataframe()\n    train_ds, val_ds, train_headlines = make_datasets(df, batch_size=global_batch_size)\n\n    # Explicit sharding policy: DATA means each worker sees a shard of the\n    # dataset rather than the whole thing. This is a no-op with one worker\n    # but is the setting that matters once you move to\n    # MultiWorkerMirroredStrategy.\n    options = tf.data.Options()\n    options.experimental_distribute.auto_shard_policy = tf.data.experimental.AutoShardPolicy.DATA\n    train_ds = train_ds.with_options(options)\n    val_ds = val_ds.with_options(options)\n\n    # TextVectorization is adapted once, outside strategy.scope(), then\n    # baked into the model — vocabulary/lookup tables aren't themselves\n    # mirrored trainable variables.\n    text_vectorizer = build_text_vectorizer(train_headlines)\n\n    with strategy.scope():\n        model = build_model(text_vectorizer)\n        model.compile(\n            optimizer=tf.keras.optimizers.Adam(learning_rate=1e-3),\n            loss=\"sparse_categorical_crossentropy\",\n            metrics=[\"accuracy\"],\n        )\n\n    model.summary()\n\n    history = model.fit(\n        train_ds,\n        validation_data=val_ds,\n        epochs=EPOCHS,\n    )\n\n    os.makedirs(MODEL_OUT_DIR, exist_ok=True)\n    model.export(MODEL_OUT_DIR)\n    print(f\"Saved trained model to {MODEL_OUT_DIR}\")\n\n    final_val_acc = history.history[\"val_accuracy\"][-1]\n    print(f\"Final validation accuracy: {final_val_acc:.3f}\")\n    return model, history\n\n\nif __name__ == \"__main__\":\n    main()\n"}, {"title": "TFLite quantization + benchmark", "path": "multimodal-market-signal/multimodal-market-signal/src/quantize_and_benchmark.py", "code": "\"\"\"\nquantize_and_benchmark.py\n────────────────────────────\nInference optimization: converts the trained SavedModel to TFLite with\npost-training dynamic-range quantization, then benchmarks the quantized\nmodel against the original on the same batch of inputs — real numbers,\nnot estimates:\n\n  - On-disk size (SavedModel dir vs .tflite file)\n  - Per-sample inference latency (Keras/TF runtime vs TFLite interpreter)\n\nRun `python -m src.train_distributed` first to produce ../saved_model.\n\"\"\"\n\nimport os\nimport time\n\nimport numpy as np\nimport tensorflow as tf\n\nfrom src.data_pipeline import load_dataframe, make_datasets\n\nSAVED_MODEL_DIR = os.path.join(os.path.dirname(__file__), \"..\", \"saved_model\")\nTFLITE_PATH = os.path.join(os.path.dirname(__file__), \"..\", \"model_quantized.tflite\")\nBENCHMARK_N = 200\n\n\ndef _dir_size_bytes(path: str) -> int:\n    total = 0\n    for root, _, files in os.walk(path):\n        for f in files:\n            total += os.path.getsize(os.path.join(root, f))\n    return total\n\n\ndef convert_to_tflite():\n    converter = tf.lite.TFLiteConverter.from_saved_model(SAVED_MODEL_DIR)\n    # Dynamic-range quantization: weights stored as int8, activations\n    # computed in float at inference time. Doesn't need a representative\n    # dataset (unlike full-integer quantization), and is the safest\n    # default speed/size win for a model this small.\n    converter.optimizations = [tf.lite.Optimize.DEFAULT]\n    # The Bidirectional LSTM branch lowers to a dynamic TensorList op that\n    # TFLite's built-in op set can't legalize on its own. Falling back to\n    # TF's op kernels (SELECT_TF_OPS) for just that op is the documented\n    # fix — everything else in the graph still converts to native TFLite\n    # ops, so this only costs a slightly larger runtime, not the whole\n    # size/speed benefit of quantization.\n    converter.target_spec.supported_ops = [\n        tf.lite.OpsSet.TFLITE_BUILTINS,\n        tf.lite.OpsSet.SELECT_TF_OPS,\n    ]\n    converter._experimental_lower_tensor_list_ops = False\n    tflite_model = converter.convert()\n    with open(TFLITE_PATH, \"wb\") as f:\n        f.write(tflite_model)\n    return TFLITE_PATH\n\n\n# Note on what SELECT_TF_OPS actually costs: the text branch's TextVectorization\n# and the Bidirectional LSTM lower to a handful of ops (string splitting,\n# TensorList reserve/stack, ragged-to-dense) that aren't in TFLite's builtin\n# op set and get delegated to the \"Flex\" TF runtime instead of native TFLite\n# kernels. That's why this still needs the full TensorFlow package at\n# inference time (or the tflite-runtime + flex-delegate build) rather than\n# the minimal tflite-runtime-only deployment you'd get with a pure-numeric\n# model. Worth knowing before claiming this is \"edge-deployable\" as-is —\n# it's real quantization and a real, measured speed/size win, but the text\n# branch keeps it dependent on TF's runtime rather than the lightest-weight\n# TFLite deployment path.\n\n\ndef _benchmark_keras(saved_model_dir: str, inputs: dict, n_runs: int) -> float:\n    infer = tf.saved_model.load(saved_model_dir).signatures[\"serving_default\"]\n    # Warm-up (first call pays graph-tracing / lazy-init cost)\n    infer(**inputs)\n    start = time.perf_counter()\n    for _ in range(n_runs):\n        infer(**inputs)\n    elapsed = time.perf_counter() - start\n    return elapsed / n_runs\n\n\ndef _benchmark_tflite(tflite_path: str, inputs: dict, n_runs: int) -> float:\n    interpreter = tf.lite.Interpreter(model_path=tflite_path)\n    interpreter.allocate_tensors()\n    input_details = {d[\"name\"]: d for d in interpreter.get_input_details()}\n\n    def _set_inputs():\n        for name, detail in input_details.items():\n            # TFLite input tensor names are like \"serving_default_headline:0\"\n            key = next(k for k in inputs if k in name)\n            interpreter.set_tensor(detail[\"index\"], inputs[key])\n\n    _set_inputs()\n    interpreter.invoke()  # warm-up\n\n    start = time.perf_counter()\n    for _ in range(n_runs):\n        _set_inputs()\n        interpreter.invoke()\n    elapsed = time.perf_counter() - start\n    return elapsed / n_runs\n\n\ndef main():\n    if not os.path.exists(SAVED_MODEL_DIR):\n        raise FileNotFoundError(\n            f\"{SAVED_MODEL_DIR} not found. Run `python -m src.train_distributed` first.\"\n        )\n\n    tflite_path = convert_to_tflite()\n\n    df = load_dataframe()\n    _, val_ds, _ = make_datasets(df, batch_size=1)\n    single_batch = next(iter(val_ds.take(1)))[0]\n    single_batch = {k: v.numpy() for k, v in single_batch.items()}\n\n    keras_size = _dir_size_bytes(SAVED_MODEL_DIR)\n    tflite_size = os.path.getsize(tflite_path)\n\n    keras_latency = _benchmark_keras(SAVED_MODEL_DIR, single_batch, BENCHMARK_N)\n    tflite_latency = _benchmark_tflite(tflite_path, single_batch, BENCHMARK_N)\n\n    print(\"── Size ─────────────────────────────────────────────\")\n    print(f\"SavedModel dir : {keras_size / 1024:.1f} KB\")\n    print(f\"TFLite file    : {tflite_size / 1024:.1f} KB\")\n    print(f\"Size reduction : {(1 - tflite_size / keras_size) * 100:.1f}%\")\n    print()\n    print(f\"── Latency (avg over {BENCHMARK_N} single-sample calls) ──\")\n    print(f\"Keras/TF runtime : {keras_latency * 1000:.3f} ms/sample\")\n    print(f\"TFLite runtime   : {tflite_latency * 1000:.3f} ms/sample\")\n    print(f\"Speedup          : {keras_latency / tflite_latency:.2f}x\")\n\n\nif __name__ == \"__main__\":\n    main()\n"}, {"title": "DPO toy implementation", "path": "multimodal-market-signal/multimodal-market-signal/alignment/dpo_toy_demo.py", "code": "\"\"\"\ndpo_toy_demo.py\n──────────────────\nA small, from-scratch implementation of Direct Preference Optimization\n(DPO) on a tiny word-level LSTM language model. See README.md in this\ndirectory for what this does and doesn't demonstrate.\n\nPipeline\n----------\n1. Generate synthetic (prompt, chosen, rejected) preference triples:\n   prompt = a bare headline fact, chosen = a concise/neutral summary of\n   it, rejected = a verbose/sensational summary of the same fact.\n2. Build a tiny word-level vocabulary and tokenize everything to fixed\n   prompt/response lengths.\n3. Build a policy LM (Embedding -> LSTM -> Dense(vocab)) and take a\n   frozen deep copy of its *initial* weights as the reference model.\n4. Train the policy with the real DPO loss:\n     L = -log(sigmoid(beta * ((logp_pi(chosen|x) - logp_ref(chosen|x))\n                             - (logp_pi(rejected|x) - logp_ref(rejected|x)))))\n5. Report the DPO loss curve and the preference margin\n   (logp(chosen) - logp(rejected)) under the policy vs. under the frozen\n   reference, before and after training.\n\"\"\"\n\nimport random\n\nimport numpy as np\nimport tensorflow as tf\n\nSEED = 7\nPROMPT_LEN = 6\nRESPONSE_LEN = 10\nEMBED_DIM = 32\nLSTM_UNITS = 64\nBETA = 0.5\nLEARNING_RATE = 5e-3\nEPOCHS = 60\nBATCH_SIZE = 16\n\nPAD_ID = 0\nUNK_ID = 1\n\nTICKERS = [\"ACME\", \"NORTH\", \"BLUE\", \"SUMMIT\", \"DELTA\", \"ORION\"]\nEVENTS = [\n    (\"beat earnings estimates\", \"beats estimates\"),\n    (\"missed revenue targets\", \"misses targets\"),\n    (\"announced a new product line\", \"launches new product\"),\n    (\"cut its full year guidance\", \"cuts guidance\"),\n    (\"raised its dividend\", \"raises dividend\"),\n    (\"completed a share buyback\", \"completes buyback\"),\n]\n\nVERBOSE_TEMPLATES = [\n    \"BREAKING: {ticker} stuns markets as it {fact}, sending shockwaves through Wall Street\",\n    \"In a dramatic turn of events {ticker} {fact} and investors are scrambling to react\",\n    \"{ticker} sent the market into a frenzy after it {fact} this morning\",\n]\nCONCISE_TEMPLATES = [\n    \"{ticker} {short}\",\n    \"{ticker}: {short}\",\n    \"{ticker} today {short}\",\n]\nPROMPT_TEMPLATES = [\n    \"{ticker} {fact}\",\n]\n\n\ndef _tokenize(text: str):\n    return text.lower().replace(\":\", \"\").split()\n\n\ndef generate_preference_data(seed: int = SEED):\n    rng = random.Random(seed)\n    triples = []\n    for ticker in TICKERS:\n        for fact, short in EVENTS:\n            prompt = rng.choice(PROMPT_TEMPLATES).format(ticker=ticker, fact=fact)\n            chosen = rng.choice(CONCISE_TEMPLATES).format(ticker=ticker, short=short)\n            rejected = rng.choice(VERBOSE_TEMPLATES).format(ticker=ticker, fact=fact)\n            triples.append((prompt, chosen, rejected))\n    rng.shuffle(triples)\n    return triples\n\n\ndef build_vocab(triples):\n    vocab = {\"<pad>\": PAD_ID, \"<unk>\": UNK_ID}\n    for prompt, chosen, rejected in triples:\n        for text in (prompt, chosen, rejected):\n            for tok in _tokenize(text):\n                if tok not in vocab:\n                    vocab[tok] = len(vocab)\n    return vocab\n\n\ndef encode(text: str, vocab: dict, length: int):\n    ids = [vocab.get(tok, UNK_ID) for tok in _tokenize(text)]\n    ids = ids[:length]\n    ids = ids + [PAD_ID] * (length - len(ids))\n    return ids\n\n\ndef build_model(vocab_size: int) -> tf.keras.Model:\n    inputs = tf.keras.Input(shape=(PROMPT_LEN + RESPONSE_LEN - 1,), dtype=tf.int32)\n    x = tf.keras.layers.Embedding(vocab_size, EMBED_DIM, mask_zero=False)(inputs)\n    x = tf.keras.layers.LSTM(LSTM_UNITS, return_sequences=True)(x)\n    logits = tf.keras.layers.Dense(vocab_size)(x)\n    return tf.keras.Model(inputs, logits)\n\n\ndef sequence_logprob(model, full_ids: tf.Tensor, response_mask: tf.Tensor) -> tf.Tensor:\n    \"\"\"\n    full_ids: (batch, PROMPT_LEN + RESPONSE_LEN) int32 token ids.\n    response_mask: (batch, PROMPT_LEN + RESPONSE_LEN - 1) 1.0 where the\n      *target* position (t+1) is a real, non-pad response token.\n    Returns: (batch,) sum of log p(target_t | tokens_<=t) over masked positions\n      — i.e. logp(response | prompt) under teacher forcing.\n    \"\"\"\n    inputs = full_ids[:, :-1]\n    targets = full_ids[:, 1:]\n    logits = model(inputs, training=True)\n    log_probs = tf.nn.log_softmax(logits, axis=-1)\n    target_log_probs = tf.gather(log_probs, targets, batch_dims=2)\n    masked = target_log_probs * response_mask\n    return tf.reduce_sum(masked, axis=1)\n\n\ndef dpo_loss(policy, reference, batch, beta: float):\n    full_ids, mask_chosen, mask_rejected, full_ids_rejected = batch\n\n    logp_pi_chosen = sequence_logprob(policy, full_ids, mask_chosen)\n    logp_pi_rejected = sequence_logprob(policy, full_ids_rejected, mask_rejected)\n    logp_ref_chosen = sequence_logprob(reference, full_ids, mask_chosen)\n    logp_ref_rejected = sequence_logprob(reference, full_ids_rejected, mask_rejected)\n\n    pi_logratios = logp_pi_chosen - logp_pi_rejected\n    ref_logratios = logp_ref_chosen - logp_ref_rejected\n    logits = beta * (pi_logratios - ref_logratios)\n\n    loss = -tf.math.log_sigmoid(logits)\n    margin = pi_logratios  # policy's current preference margin, for logging\n    return tf.reduce_mean(loss), tf.reduce_mean(margin)\n\n\ndef make_batches(triples, vocab):\n    full_chosen, full_rejected, mask_chosen, mask_rejected = [], [], [], []\n    total_len = PROMPT_LEN + RESPONSE_LEN\n\n    for prompt, chosen, rejected in triples:\n        prompt_ids = encode(prompt, vocab, PROMPT_LEN)\n        chosen_ids = encode(chosen, vocab, RESPONSE_LEN)\n        rejected_ids = encode(rejected, vocab, RESPONSE_LEN)\n\n        full_chosen.append(prompt_ids + chosen_ids)\n        full_rejected.append(prompt_ids + rejected_ids)\n\n        # mask over target positions (length total_len - 1): position t\n        # predicts token t+1; we score t+1 in [PROMPT_LEN, total_len-1]\n        # and require it not be padding.\n        m_chosen = np.zeros(total_len - 1, dtype=\"float32\")\n        m_rejected = np.zeros(total_len - 1, dtype=\"float32\")\n        for t in range(PROMPT_LEN - 1, total_len - 1):\n            if full_chosen[-1][t + 1] != PAD_ID:\n                m_chosen[t] = 1.0\n            if full_rejected[-1][t + 1] != PAD_ID:\n                m_rejected[t] = 1.0\n        mask_chosen.append(m_chosen)\n        mask_rejected.append(m_rejected)\n\n    return (\n        np.array(full_chosen, dtype=\"int32\"),\n        np.array(mask_chosen, dtype=\"float32\"),\n        np.array(mask_rejected, dtype=\"float32\"),\n        np.array(full_rejected, dtype=\"int32\"),\n    )\n\n\ndef main():\n    tf.random.set_seed(SEED)\n    np.random.seed(SEED)\n\n    triples = generate_preference_data()\n    vocab = build_vocab(triples)\n    print(f\"{len(triples)} preference pairs, vocab size {len(vocab)}\")\n\n    full_chosen, mask_chosen, mask_rejected, full_rejected = make_batches(triples, vocab)\n\n    policy = build_model(len(vocab))\n    policy.build(input_shape=(None, PROMPT_LEN + RESPONSE_LEN - 1))\n\n    reference = build_model(len(vocab))\n    reference.build(input_shape=(None, PROMPT_LEN + RESPONSE_LEN - 1))\n    reference.set_weights(policy.get_weights())  # frozen copy of the INITIAL policy\n    reference.trainable = False\n\n    optimizer = tf.keras.optimizers.Adam(learning_rate=LEARNING_RATE)\n\n    n = len(triples)\n\n    def eval_margin(model):\n        _, margin = dpo_loss(\n            model, reference,\n            (full_chosen, mask_chosen, mask_rejected, full_rejected),\n            BETA,\n        )\n        return float(margin)\n\n    print(f\"Policy preference margin before training: {eval_margin(policy):.4f}\")\n\n    indices = np.arange(n)\n    for epoch in range(EPOCHS):\n        np.random.shuffle(indices)\n        epoch_losses = []\n        for start in range(0, n, BATCH_SIZE):\n            batch_idx = indices[start:start + BATCH_SIZE]\n            batch = (\n                full_chosen[batch_idx],\n                mask_chosen[batch_idx],\n                mask_rejected[batch_idx],\n                full_rejected[batch_idx],\n            )\n            with tf.GradientTape() as tape:\n                loss, _ = dpo_loss(policy, reference, batch, BETA)\n            grads = tape.gradient(loss, policy.trainable_variables)\n            optimizer.apply_gradients(zip(grads, policy.trainable_variables))\n            epoch_losses.append(float(loss))\n\n        if epoch % 10 == 0 or epoch == EPOCHS - 1:\n            print(f\"epoch {epoch:3d}  dpo_loss={np.mean(epoch_losses):.4f}\")\n\n    print(f\"Policy preference margin after training:  {eval_margin(policy):.4f}\")\n    print(\n        \"\\nA rising margin (logp(chosen) - logp(rejected) under the policy) means \"\n        \"the model increasingly assigns higher likelihood to the concise/neutral \"\n        \"response over the verbose/sensational one, relative to where the frozen \"\n        \"reference started.\"\n    )\n\n\nif __name__ == \"__main__\":\n    main()\n"}], "decision": [{"title": "Core decision engine", "path": "decision-forge-main/decision-forge-main/app/core/decision_engine.py", "code": "\"\"\"\nDecision Engine\n---------------\nConverts ML scores into accountable business actions with latency tracking.\n\nSystem Design Trade-offs\n-------------------------\n1. Latency vs Accuracy\n   - We use Logistic Regression + Isolation Forest instead of deep models.\n     This gives ~0.1–2ms inference latency vs 50–200ms for neural networks.\n     Acceptable accuracy loss for real-time customer-facing decisions.\n\n2. Synchronous vs Async\n   - Current implementation is synchronous (simple, easy to debug).\n   - For >1000 req/sec, this should move to async FastAPI + worker pool.\n\n3. Thresholds in YAML vs Model\n   - ROI/anomaly thresholds live in YAML, not hardcoded.\n   - This lets business teams tune without re-deploying code.\n\n4. Audit Log\n   - Every decision is logged with inputs + rationale.\n   - Adds ~0.5ms overhead per request but is mandatory for compliance.\n\"\"\"\n\nimport time\nfrom app.core.roi import ROICalculator\nfrom app.core.security import SecurityGate\nfrom app.core.audit import AuditLogger\n\n\nclass DecisionEngine:\n    \"\"\"\n    Routes ML predictions to business actions: INTERVENE, DO_NOTHING, or FLAG.\n\n    Decision hierarchy (evaluated in order):\n        1. Security Gate  — block or flag suspicious behavior first\n        2. ROI Check      — only intervene if expected value is positive\n        3. Default        — do nothing\n    \"\"\"\n\n    def __init__(self, config: dict):\n        \"\"\"\n        Args:\n            config : loaded YAML config dict containing thresholds and costs\n        \"\"\"\n        self.config = config\n        self.roi_calculator = ROICalculator(config)\n        self.security_gate = SecurityGate(config)\n        self.audit_logger = AuditLogger()\n\n    def decide(self, inputs: dict) -> dict:\n        \"\"\"\n        Make a real-time decision for a single user.\n\n        Args:\n            inputs : dict containing:\n                - churn_probability  (float)  : model output, 0–1\n                - expected_lift      (float)  : estimated retention lift from intervention\n                - anomaly_score      (float)  : 0–1, higher = more suspicious\n                - request_count_today(int)    : raw request volume feature\n\n        Returns:\n            dict with keys:\n                - decision       : \"INTERVENE\" | \"DO_NOTHING\" | \"FLAG\"\n                - reason         : human-readable explanation string\n                - expected_value : estimated $ value of the decision\n                - latency_ms     : time taken for this decision in milliseconds\n        \"\"\"\n        start_time = time.perf_counter()\n\n        # --- Step 1: Security Gate ---\n        security_result = self.security_gate.evaluate(inputs)\n        if security_result[\"action\"] in (\"BLOCK\", \"FLAG\"):\n            decision = {\n                \"decision\": \"FLAG\",\n                \"reason\": security_result[\"reason\"],\n                \"expected_value\": 0.0,\n            }\n            latency_ms = round((time.perf_counter() - start_time) * 1000, 3)\n            decision[\"latency_ms\"] = latency_ms\n            self.audit_logger.log(inputs, decision)\n            return decision\n\n        # --- Step 2: ROI Check ---\n        roi_result = self.roi_calculator.evaluate(inputs)\n        if roi_result[\"roi_positive\"]:\n            decision = {\n                \"decision\": \"INTERVENE\",\n                \"reason\": roi_result[\"reason\"],\n                \"expected_value\": roi_result[\"expected_value\"],\n            }\n        else:\n            decision = {\n                \"decision\": \"DO_NOTHING\",\n                \"reason\": roi_result[\"reason\"],\n                \"expected_value\": roi_result[\"expected_value\"],\n            }\n\n        # --- Step 3: Record latency ---\n        latency_ms = round((time.perf_counter() - start_time) * 1000, 3)\n        decision[\"latency_ms\"] = latency_ms\n\n        # --- Step 4: Audit ---\n        self.audit_logger.log(inputs, decision)\n\n        return decision\n\n    def get_latency_profile(self) -> dict:\n        \"\"\"\n        Return system design notes on latency vs accuracy trade-offs.\n        Useful for API /health and /metrics endpoints.\n        \"\"\"\n        return {\n            \"model_inference_ms\": \"~0.1–2ms (Logistic Regression + Isolation Forest)\",\n            \"roi_calc_ms\": \"~0.01ms\",\n            \"security_gate_ms\": \"~0.01ms\",\n            \"audit_log_ms\": \"~0.5ms\",\n            \"total_p99_ms\": \"~5ms\",\n            \"trade_off_note\": (\n                \"Chosen models optimize for latency. Switching to XGBoost would \"\n                \"improve F1 by ~5–10% but increase inference latency to ~10–20ms. \"\n                \"Acceptable for batch use cases, not for <5ms SLA requirements.\"\n            ),\n        }"}, {"title": "AI-enhanced engine", "path": "decision-forge-main/decision-forge-main/app/ai/ai_enhanced_engine.py", "code": "\"\"\"\nAI-Enhanced Decision Engine (Ollama version - FREE)\nWraps the core DecisionEngine with AI capabilities.\n\"\"\"\n\nfrom typing import Dict, Any, List, Optional\nfrom app.core.decision_engine import DecisionEngine\nfrom app.ai.ai_explainer import AIExplainer, AIInsightsGenerator\nimport logging\n\nlogger = logging.getLogger(__name__)\n\n\nclass AIEnhancedDecisionEngine:\n    \"\"\"\n    Enhanced decision engine with AI-powered explanations using Ollama.\n    \"\"\"\n    \n    def __init__(\n        self,\n        config: Dict[str, Any],\n        enable_ai: bool = True,\n        model: str = \"llama3.2\"\n    ):\n        \"\"\"Initialize the AI-enhanced decision engine.\"\"\"\n        self.base_engine = DecisionEngine(config)\n        self.enable_ai = enable_ai\n        \n        if enable_ai:\n            try:\n                self.explainer = AIExplainer(model=model)\n                self.insights_generator = AIInsightsGenerator(model=model)\n                logger.info(f\"AI features enabled with model: {model}\")\n            except Exception as e:\n                logger.warning(f\"Failed to initialize AI: {e}. Falling back to base engine.\")\n                self.enable_ai = False\n        \n        self.decision_history = []\n    \n    def decide_with_explanation(\n        self,\n        inputs: Dict[str, Any],\n        return_explanation: bool = True,\n        return_recommendations: bool = False,\n        user_context: Dict[str, Any] = None\n    ) -> Dict[str, Any]:\n        \"\"\"Make a decision and optionally return AI-generated explanation.\"\"\"\n        # Get base decision\n        decision = self.base_engine.decide(inputs)\n        \n        result = {\n            'decision': decision,\n            'inputs': inputs\n        }\n        \n        # Add to history\n        self.decision_history.append(result.copy())\n        \n        # Generate AI enhancements if enabled\n        if self.enable_ai:\n            try:\n                if return_explanation:\n                    explanation = self.explainer.explain_decision(\n                        decision, inputs, user_context\n                    )\n                    result['explanation'] = explanation\n                \n                if return_recommendations and decision['decision'] in ['INTERVENE', 'FLAG']:\n                    recommendations = self.explainer.explain_intervention_recommendation(\n                        decision,\n                        inputs,\n                        decision.get('expected_value', 0)\n                    )\n                    result['recommendations'] = recommendations\n            \n            except Exception as e:\n                logger.error(f\"AI enhancement failed: {e}\")\n                result['ai_error'] = str(e)\n        \n        return result\n    \n    def generate_intervention_package(\n        self,\n        inputs: Dict[str, Any],\n        customer_profile: Dict[str, Any]\n    ) -> Dict[str, Any]:\n        \"\"\"Generate a complete intervention package.\"\"\"\n        result = self.decide_with_explanation(\n            inputs,\n            return_explanation=True,\n            return_recommendations=True\n        )\n        \n        decision = result['decision']\n        \n        # Generate personalized message if intervention recommended\n        if self.enable_ai and decision['decision'] == 'INTERVENE':\n            try:\n                offer_details = self._determine_offer(\n                    decision.get('expected_value', 0),\n                    inputs\n                )\n                \n                personalized_message = self.explainer.generate_personalized_message(\n                    customer_profile,\n                    intervention_type='retention',\n                    offer_details=offer_details\n                )\n                \n                result['personalized_message'] = personalized_message\n                result['offer_details'] = offer_details\n            \n            except Exception as e:\n                logger.error(f\"Message generation failed: {e}\")\n                result['message_error'] = str(e)\n        \n        return result\n    \n    def batch_process_with_explanations(\n        self,\n        user_inputs: List[Dict[str, Any]],\n        include_explanations: bool = True\n    ) -> List[Dict[str, Any]]:\n        \"\"\"Process multiple users and generate decisions with explanations.\"\"\"\n        results = []\n        \n        for inputs in user_inputs:\n            result = self.decide_with_explanation(\n                inputs,\n                return_explanation=include_explanations\n            )\n            results.append(result)\n        \n        return results\n    \n    def get_strategic_insights(\n        self,\n        time_period: str = \"recent activity\",\n        min_decisions: int = 10\n    ) -> Optional[Dict[str, Any]]:\n        \"\"\"Generate strategic insights from decision history.\"\"\"\n        if not self.enable_ai:\n            logger.warning(\"AI features not enabled\")\n            return None\n        \n        if len(self.decision_history) < min_decisions:\n            logger.warning(f\"Insufficient history: {len(self.decision_history)} < {min_decisions}\")\n            return None\n        \n        try:\n            insights = self.insights_generator.analyze_decision_patterns(\n                self.decision_history,\n                time_period=time_period\n            )\n            return insights\n        \n        except Exception as e:\n            logger.error(f\"Insights generation failed: {e}\")\n            return None\n    \n    def _determine_offer(\n        self,\n        expected_value: float,\n        inputs: Dict[str, Any]\n    ) -> Dict[str, Any]:\n        \"\"\"Determine appropriate offer.\"\"\"\n        churn_prob = inputs.get('churn', 0)\n        \n        if expected_value > 1000 or churn_prob > 0.8:\n            return {\"discount\": \"25%\", \"duration\": \"6 months\"}\n        elif expected_value > 500 or churn_prob > 0.6:\n            return {\"discount\": \"20%\", \"duration\": \"3 months\"}\n        else:\n            return {\"discount\": \"15%\", \"duration\": \"2 months\"}\n    \n    def get_decision_history_summary(self) -> Dict[str, Any]:\n        \"\"\"Get summary statistics.\"\"\"\n        if not self.decision_history:\n            return {\"message\": \"No decision history available\"}\n        \n        decision_counts = {}\n        total_value = 0\n        \n        for record in self.decision_history:\n            decision = record['decision']['decision']\n            decision_counts[decision] = decision_counts.get(decision, 0) + 1\n            total_value += record['decision'].get('expected_value', 0)\n        \n        return {\n            \"total_decisions\": len(self.decision_history),\n            \"decision_breakdown\": decision_counts,\n            \"total_expected_value\": total_value,\n            \"average_value\": total_value / len(self.decision_history)\n        }\n    \n    def clear_history(self):\n        \"\"\"Clear decision history.\"\"\"\n        self.decision_history = []"}, {"title": "AI explainer", "path": "decision-forge-main/decision-forge-main/app/ai/ai_explainer.py", "code": "\"\"\"\nAI-powered decision explainer using Ollama (FREE local AI).\n\"\"\"\n\nfrom typing import Dict, Any, List\nimport ollama\n\n\nclass AIExplainer:\n    \"\"\"\n    Uses Ollama local AI to generate explanations for decisions.\n    \"\"\"\n    \n    def __init__(self, model: str = \"llama3.2\"):\n        \"\"\"Initialize the AI explainer with Ollama model.\"\"\"\n        self.model = model\n        # Test connection\n        try:\n            ollama.list()\n            print(f\"✓ Connected to Ollama with model: {model}\")\n        except Exception as e:\n            print(f\"⚠️  Ollama not running: {e}\")\n            print(\"Run: ollama serve\")\n    \n    def explain_decision(\n        self,\n        decision: Dict[str, Any],\n        inputs: Dict[str, Any],\n        user_context: Dict[str, Any] = None\n    ) -> str:\n        \"\"\"Generate a natural language explanation for a decision.\"\"\"\n        prompt = self._build_explanation_prompt(decision, inputs, user_context)\n        \n        try:\n            response = ollama.chat(\n                model=self.model,\n                messages=[{\"role\": \"user\", \"content\": prompt}]\n            )\n            return response['message']['content']\n        except Exception as e:\n            return f\"Error generating explanation: {e}\"\n    \n    def explain_intervention_recommendation(\n        self,\n        decision: Dict[str, Any],\n        inputs: Dict[str, Any],\n        expected_value: float\n    ) -> Dict[str, str]:\n        \"\"\"Generate detailed recommendations for intervention actions.\"\"\"\n        prompt = f\"\"\"You are an AI advisor for a customer retention system. Based on the following analysis, provide actionable recommendations:\n\nDecision: {decision['decision']}\nReason: {decision['reason']}\nExpected Value: ${expected_value:.2f}\n\nUser Metrics:\n- Anomaly Score: {inputs.get('anomaly_score', 'N/A')}\n- Request Count Today: {inputs.get('request_count_today', 'N/A')}\n- Churn Probability: {inputs.get('churn', 0) * 100:.1f}%\n\nProvide a response in this format:\nSUMMARY: [One-line summary]\nRATIONALE: [Why this decision maximizes value]\nSUGGESTED_ACTIONS: [3-4 specific actions to take]\"\"\"\n\n        try:\n            response = ollama.chat(\n                model=self.model,\n                messages=[{\"role\": \"user\", \"content\": prompt}]\n            )\n            response_text = response['message']['content']\n            return self._parse_structured_response(response_text)\n        except Exception as e:\n            return {\n                'summary': f'Error: {e}',\n                'rationale': '',\n                'suggested_actions': ''\n            }\n    \n    def generate_personalized_message(\n        self,\n        customer_profile: Dict[str, Any],\n        intervention_type: str,\n        offer_details: Dict[str, Any] = None\n    ) -> str:\n        \"\"\"Generate a personalized customer message for interventions.\"\"\"\n        prompt = f\"\"\"Generate a friendly, personalized customer retention message.\n\nCustomer Profile:\n- Tenure: {customer_profile.get('tenure', 'N/A')} months\n- Monthly Charges: ${customer_profile.get('monthly_charges', 'N/A')}\n\nIntervention Type: {intervention_type}\nOffer: {offer_details if offer_details else 'Loyalty appreciation'}\n\nWrite a warm, concise message (2-3 sentences) that:\n1. Acknowledges their loyalty\n2. Presents the offer naturally\n3. Includes a clear call-to-action\n\nWrite a complete, ready-to-send message.\"\"\"\n\n        try:\n            response = ollama.chat(\n                model=self.model,\n                messages=[{\"role\": \"user\", \"content\": prompt}]\n            )\n            return response['message']['content'].strip()\n        except Exception as e:\n            return f\"Error generating message: {e}\"\n    \n    def _build_explanation_prompt(\n        self,\n        decision: Dict[str, Any],\n        inputs: Dict[str, Any],\n        user_context: Dict[str, Any] = None\n    ) -> str:\n        \"\"\"Build a prompt for decision explanation.\"\"\"\n        context_str = \"\"\n        if user_context:\n            context_str = f\"\\n\\nAdditional Context:\\n{self._format_dict(user_context)}\"\n        \n        prompt = f\"\"\"Explain the following business decision in clear, simple language:\n\nDecision Made: {decision['decision']}\nReason: {decision['reason']}\nExpected Value: ${decision.get('expected_value', 0):.2f}\n\nInput Metrics:\n{self._format_dict(inputs)}{context_str}\n\nProvide a 2-3 sentence explanation that:\n1. States what action to take\n2. Explains why this maximizes business value\n3. Mentions key risk factors\n\nKeep it concise and actionable.\"\"\"\n        return prompt\n    \n    def _format_dict(self, data: Dict[str, Any]) -> str:\n        \"\"\"Format a dictionary for display in prompts.\"\"\"\n        lines = []\n        for key, value in data.items():\n            formatted_key = key.replace('_', ' ').title()\n            if isinstance(value, float):\n                lines.append(f\"- {formatted_key}: {value:.3f}\")\n            else:\n                lines.append(f\"- {formatted_key}: {value}\")\n        return \"\\n\".join(lines)\n    \n    def _parse_structured_response(self, response: str) -> Dict[str, str]:\n        \"\"\"Parse a structured response into components.\"\"\"\n        parts = {'summary': '', 'rationale': '', 'suggested_actions': ''}\n        current_section = None\n        lines = response.split('\\n')\n        \n        for line in lines:\n            line = line.strip()\n            if line.startswith('SUMMARY:'):\n                current_section = 'summary'\n                parts['summary'] = line.replace('SUMMARY:', '').strip()\n            elif line.startswith('RATIONALE:'):\n                current_section = 'rationale'\n                parts['rationale'] = line.replace('RATIONALE:', '').strip()\n            elif line.startswith('SUGGESTED_ACTIONS:'):\n                current_section = 'suggested_actions'\n                parts['suggested_actions'] = line.replace('SUGGESTED_ACTIONS:', '').strip()\n            elif current_section and line:\n                parts[current_section] += ' ' + line\n        \n        return parts\n\n\nclass AIInsightsGenerator:\n    \"\"\"Generates strategic insights from decision patterns using AI.\"\"\"\n    \n    def __init__(self, model: str = \"llama3.2\"):\n        self.model = model\n    \n    def analyze_decision_patterns(\n        self,\n        decision_history: List[Dict[str, Any]],\n        time_period: str = \"recent activity\"\n    ) -> Dict[str, Any]:\n        \"\"\"Analyze patterns in decision-making and provide strategic insights.\"\"\"\n        total_decisions = len(decision_history)\n        decision_counts = {}\n        total_expected_value = 0\n        \n        for record in decision_history:\n            decision = record['decision']['decision']\n            decision_counts[decision] = decision_counts.get(decision, 0) + 1\n            total_expected_value += record['decision'].get('expected_value', 0)\n        \n        stats_summary = f\"\"\"Decision Statistics for {time_period}:\n- Total Decisions: {total_decisions}\n- Decision Breakdown: {decision_counts}\n- Total Expected Value: ${total_expected_value:.2f}\n- Average Value per Decision: ${total_expected_value / max(total_decisions, 1):.2f}\"\"\"\n\n        prompt = f\"\"\"Analyze these decision-making patterns and provide strategic insights:\n\n{stats_summary}\n\nProvide:\n1. KEY TRENDS: What patterns do you see?\n2. OPPORTUNITIES: Where can we improve ROI?\n3. RISKS: What concerns should we monitor?\n4. RECOMMENDATIONS: 3 specific actions to optimize decision-making\n\nBe specific and actionable.\"\"\"\n\n        try:\n            response = ollama.chat(\n                model=self.model,\n                messages=[{\"role\": \"user\", \"content\": prompt}]\n            )\n            \n            return {\n                'analysis': response['message']['content'],\n                'statistics': {\n                    'total_decisions': total_decisions,\n                    'decision_counts': decision_counts,\n                    'total_expected_value': total_expected_value\n                }\n            }\n        except Exception as e:\n            return {\n                'analysis': f'Error generating insights: {e}',\n                'statistics': {}\n            }"}, {"title": "React shell", "path": "decision-forge-main/decision-forge-main/frontend/src/App.jsx", "code": "import { NavLink, Route, Routes } from \"react-router-dom\";\nimport { AuthProvider, useAuth } from \"./context/AuthContext\";\nimport ProtectedRoute from \"./context/ProtectedRoute\";\nimport Dashboard from \"./pages/Dashboard\";\nimport History from \"./pages/History\";\nimport Login from \"./pages/Login\";\nimport Register from \"./pages/Register\";\n\nfunction Shell({ children }) {\n  const { user, logout } = useAuth();\n  return (\n    <div className=\"shell\">\n      <header className=\"topbar\">\n        <span className=\"brand\">DecisionForge</span>\n        {user && (\n          <nav>\n            <NavLink to=\"/\" end>\n              Dashboard\n            </NavLink>\n            <NavLink to=\"/history\">History</NavLink>\n          </nav>\n        )}\n        {user && (\n          <div className=\"user-menu\">\n            <span>\n              {user.username} · {user.role}\n            </span>\n            <button onClick={logout}>Logout</button>\n          </div>\n        )}\n      </header>\n      <main>{children}</main>\n    </div>\n  );\n}\n\nexport default function App() {\n  return (\n    <AuthProvider>\n      <Shell>\n        <Routes>\n          <Route path=\"/login\" element={<Login />} />\n          <Route path=\"/register\" element={<Register />} />\n          <Route\n            path=\"/\"\n            element={\n              <ProtectedRoute>\n                <Dashboard />\n              </ProtectedRoute>\n            }\n          />\n          <Route\n            path=\"/history\"\n            element={\n              <ProtectedRoute>\n                <History />\n              </ProtectedRoute>\n            }\n          />\n        </Routes>\n      </Shell>\n    </AuthProvider>\n  );\n}\n"}]};